INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('1', '16784', NULL, '[6,13,19,32,41]', NULL, NULL, NULL, '{\"en\":\"G833\",\"ar\":\"G833\"}', 'g833-2', 'g833-2', '{\"en\":\"<div class=\\\"grid-item grid-item-233-1-1-2\\\">\\n<div class=\\\"module module-blocks module-blocks-48 blocks-grid\\\">\\n<div class=\\\"module-body\\\">\\n<div class=\\\"module-item module-item-1\\\">\\n<div class=\\\"block-body expand-block\\\">\\n<div class=\\\"block-wrapper\\\">\\n<div class=\\\"block-content block-description\\\">\\n<p>اكتشف هدية فريدة من نوعها تجمع بين الجمال والمذاق! وينبض بالحيوية والفخامة، يجمع بين جمال الطبيعة ونضارة الفاكهة في تنسيق فريد داخل فازة أنيقة. يحتوي على 4 حبات تفاح أخضر، و6 حبات ليمون طازج، و10 ورود روز صفراء، و3 زهور ليليوم وردي تضيف لمسة أنثوية راقية، مع 3 الكريزنتيموم، و3 كيرميت، وورود السوليداجو، وجبسوفيليا وستيل قراس وخضارات طبيعية تضفي تناغمًا وأناقة على التصميم. تنسيق مثالي يعبّر عن البهجة والتجدد، مناسب للهدايا المميزة والمناسبات المشرقة.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\\n</div>\\n</div>\\n</div>\\n</div>\\n</div>\\n</div>\\n</div>\",\"ar\":\"<div class=\\\"grid-item grid-item-233-1-1-2\\\">\\n<div class=\\\"module module-blocks module-blocks-48 blocks-grid\\\">\\n<div class=\\\"module-body\\\">\\n<div class=\\\"module-item module-item-1\\\">\\n<div class=\\\"block-body expand-block\\\">\\n<div class=\\\"block-wrapper\\\">\\n<div class=\\\"block-content block-description\\\">\\n<p>اكتشف هدية فريدة من نوعها تجمع بين الجمال والمذاق! وينبض بالحيوية والفخامة، يجمع 