INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('13', '16844', NULL, '[6,19,20,22,25,32]', NULL, NULL, NULL, '{\"en\":\"G743\",\"ar\":\"G743\"}', 'g743-2', 'g743-2', '{\"en\":\"<p>باقة صُممت بعناية فائقة على يد خبرائنا، الذين حرصوا على تنسيقها بذوق رفيع يترك انطباعًا جماليًا راقيًا وحصريًا، لتُقدَّم بكل تألق لعملائنا المميزين.بباقة مليئة بالأزهار بألوان متناسقة ومبهجة، حيث تحتوي على زهور السمبيديوم الأخضر الفاتح, الليليوم الأبيض, والبيبي جوري البنفسجي الفاتح , مع تداخلات الجوري الزهري الفاتح والأبيض , يكسرها الزهر الاستوما والاستومريا باللون البنفسجي الغامق لتعطي إحساس راقي للباقة، اضفنا اللمسات الساحرة الرقيقة من  الستيل غراس وخضار اليوكالبتوس مع الليمينيوم الزهري الفاتح</p>\\n<p>الاختيار المثالي لكل من يستحق لحظات لا تُنسى.</p>\\n<p>الارتفاع حوالي 65 سم إلى 70 سم.</p>\\n<p>العرض حوالي 45 سم إلى 50 سم.</p>\",\"ar\":\"<p>باقة صُممت بعناية فائقة على يد خبرائنا، الذين حرصوا على تنسيقها بذوق رفيع يترك انطباعًا جماليًا راقيًا وحصريًا، لتُقدَّم بكل تألق لعملائنا المميزين.بباقة مليئة بالأزهار بألوان متناسقة ومبهجة، حيث تحتوي على زهور السمبيديوم الأخضر الفاتح, الليليوم الأبيض, والبيبي جوري البنفسجي الفاتح , مع تداخلات الجوري الزهري الفاتح والأبيض , يكسرها الزهر الاستوما والاستومريا باللون البنفسجي الغامق لتعطي إحساس راقي للباقة، اضفنا اللمسات الساحرة الرقيقة من  الستيل غراس وخضار اليوكالبتوس مع الليمينيوم الزهري الفاتح</p>\\n<p>الاختيار المثالي لكل من يستحق لحظات لا تُنسى.</p>\\n<p>الارتفاع حوالي 65 سم إلى 70 سم.</p>\\n<p>العرض حوالي 45 سم إلى 50 سم.</p>\"}', '1324', 'products/104-1.jpg', '[\"products\\/gallery\\/10