INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('16', '16852', NULL, '[6,7,21,32,46]', NULL, NULL, NULL, '{\"en\":\"G734\",\"ar\":\"G734\"}', 'g734-2', 'g734-2', '{\"en\":\"<p>باقة من 20 روز برتقالية مذهلة، تتميز بألوانها الدافئة والجذابة التي تضفي لمسة من الفرح والحيوية على أي مناسبة. يتميز هذا التشكيل بتنسيق رائع وأنيق، حيث تم ربط الزهور بشريط برتقالي يضيف لمسة من الرقة والتميز. سواء كنت ترغب في إرسال تحية محبة أو إضافة لمسة خاصة لديكور منزلك، فإن هذه الباقة ستكون الخيار المثالي لإظهار الذوق الرفيع والتقدير. لا تفوت الفرصة لجعل لحظاتك أكثر إشراقًا وجمالًا مع هذه الورود المبهجة.</p>\\n<p>الارتفاع حوالي 35 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>باقة من 20 روز برتقالية مذهلة، تتميز بألوانها الدافئة والجذابة التي تضفي لمسة من الفرح والحيوية على أي مناسبة. يتميز هذا التشكيل بتنسيق رائع وأنيق، حيث تم ربط الزهور بشريط برتقالي يضيف لمسة من الرقة والتميز. سواء كنت ترغب في إرسال تحية محبة أو إضافة لمسة خاصة لديكور منزلك، فإن هذه الباقة ستكون الخيار المثالي لإظهار الذوق الرفيع والتقدير. لا تفوت الفرصة لجعل لحظاتك أكثر إشراقًا وجمالًا مع هذه الورود المبهجة.</p>\\n<p>الارتفاع حوالي 35 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '1314', 'products/01-4.png', '[\"products\\/gallery\\/01-4.png\",\"products\\/gallery\\/2-46.png\",\"products\\/gallery\\/3-44.png\",\"products\\/gallery\\/4-41.png\",\"products\\/gallery\\/5-22.png\"]', '{\"en\":\"<p>باقة من 20 روز برتقالية مذهلة، تتميز بألوانها الدافئة والجذابة التي تضفي لمسة من الفرح والحيوية على أي مناسبة. يتميز هذا التشكيل بتنسيق رائع وأنيق، حيث تم ربط الزهور بشريط ب