INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('29', '16882', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G715\",\"ar\":\"G715\"}', 'g715-2', 'g715-2', '{\"en\":\"<p>تنسيق فاخر مفعم بالحيوية يجمع بين فخامة الورود ونضارة الفاكهة في فازة زجاجية أنيقة، يحتوي على فراولة طازجة، وتفاح أخضر وأحمر، وبرتقال وكمثرى، مع ورود برتقالية (7 حبات) وورود صفراء (7 حبات) وأيضا ورود حمراء (10)</p>\\n<p>بالإضافة الى الكريزنتيموم الأصفر (3 حبات)، وهايبركوم أحمر (5 حبات)، وكيرميت (5 حبات).</p>\\n<p>تناغم الألوان الحمراء والبرتقالية والصفراء يمنح التصميم طاقة مبهجة وأناقة راقية، مما يجعله خيارًا مثاليًا للهدايا والمناسبات الخاصة.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>تنسيق فاخر مفعم بالحيوية يجمع بين فخامة الورود ونضارة الفاكهة في فازة زجاجية أنيقة، يحتوي على فراولة طازجة، وتفاح أخضر وأحمر، وبرتقال وكمثرى، مع ورود برتقالية (7 حبات) وورود صفراء (7 حبات) وأيضا ورود حمراء (10)</p>\\n<p>بالإضافة الى الكريزنتيموم الأصفر (3 حبات)، وهايبركوم أحمر (5 حبات)، وكيرميت (5 حبات).</p>\\n<p>تناغم الألوان الحمراء والبرتقالية والصفراء يمنح التصميم طاقة مبهجة وأناقة راقية، مما يجعله خيارًا مثاليًا للهدايا والمناسبات الخاصة.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '1291', 'products/101-52.png', '[\"products\\/gallery\\/101-52.png\",\"products\\/gallery\\/103-49.png\",\"products\\/gallery\\/104-42.png\",\"products\\/gallery\\/105-30.png\"]', '{\"en\":\"<p>تنسيق فاخر مفعم بالحيوية يجمع بين فخامة الورود ونضارة الفاكهة في فازة زجاجية أنيقة، يحتوي على فراولة طازجة، وتفاح أخضر وأحمر، وبرتقال