INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('36', '16914', NULL, '[6,7,16,29,32]', NULL, NULL, NULL, '{\"en\":\"G690\",\"ar\":\"G690\"}', 'g690-2', 'g690-2', '{\"en\":\"<p>تنسيق فاخر يجمع تدرجات البنفسجي والوردي بتناغم ساحر يعكس الأناقة والرقي. يتكوّن من ثمانية ورود الروز بتدرجات بنفسجية، وثلاث زهور استوما وردية فاتحة، وزهرتين من الكريزنتيموم البنفسجي الفاتح، مع ليلوم وردي وثلاث بيبي روز وردية، وخمس زهور أوركيد وردية تضيف لمسة فاخرة، تتناغم جميعها مع الخضار الطبيعي لتمنح شعورًا بالدفء والجمال المتكامل. مثالي كهدية تعبّر عن الذوق الرفيع والمشاعر الصادقة في أي مناسبة.</p>\\n<p>الارتفاع حوالي 80 سم.</p>\\n<p>العرض حوالي 60 سم.</p>\",\"ar\":\"<p>تنسيق فاخر يجمع تدرجات البنفسجي والوردي بتناغم ساحر يعكس الأناقة والرقي. يتكوّن من ثمانية ورود الروز بتدرجات بنفسجية، وثلاث زهور استوما وردية فاتحة، وزهرتين من الكريزنتيموم البنفسجي الفاتح، مع ليلوم وردي وثلاث بيبي روز وردية، وخمس زهور أوركيد وردية تضيف لمسة فاخرة، تتناغم جميعها مع الخضار الطبيعي لتمنح شعورًا بالدفء والجمال المتكامل. مثالي كهدية تعبّر عن الذوق الرفيع والمشاعر الصادقة في أي مناسبة.</p>\\n<p>الارتفاع حوالي 80 سم.</p>\\n<p>العرض حوالي 60 سم.</p>\"}', '1244', 'products/1-32.png', '[\"products\\/gallery\\/1-32.png\",\"products\\/gallery\\/2-34.png\",\"products\\/gallery\\/3-33.png\",\"products\\/gallery\\/4-31.png\",\"products\\/gallery\\/5-16.png\",\"products\\/gallery\\/6-5.png\"]', '{\"en\":\"<p>تنسيق فاخر يجمع تدرجات البنفسجي والوردي بتناغم ساحر يعكس الأناقة والرقي. يتكوّن من ثمانية ورود الروز بتدرجات بنفسجية، وثلاث زهور استوما وردية فاتحة، وزهرتين من 