INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('63', '17006', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G596\",\"ar\":\"G596\"}', 'g596-2', 'g596-2', '{\"en\":\"<p>أهدي من يعز عليك مع هذه الباقة المميزة التي تجمع بين سحر الزهور ونضارة الفواكه في تنسيق أنيق ينبض بالحياة! تتألق الباقة بـ21 وردة حمراء وبيضاء تنسجم بتناغم ساحر، يحيط بها 5 زهور كريز أبيض ولمسات ناعمة من الليمينيوم الأبيض (3) واستروميريا رقيقة (2)، مع لمسة خضراء منعشة من هيدرينجا أخضر (2). ويكتمل الجمال بفاكهة مختارة بعناية: موزتين، تفاحة حمراء، حبتين مانجو، 4 حبات ليمون، 3 جوافة، وعنقود عنب يتوّج الباقة بلمسة لافتة. تنسيق فاخر يعبّر عن الذوق الرفيع، مثالي لهدية مميزة أو لمناسبة استثنائية.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\",\"ar\":\"<p>أهدي من يعز عليك مع هذه الباقة المميزة التي تجمع بين سحر الزهور ونضارة الفواكه في تنسيق أنيق ينبض بالحياة! تتألق الباقة بـ21 وردة حمراء وبيضاء تنسجم بتناغم ساحر، يحيط بها 5 زهور كريز أبيض ولمسات ناعمة من الليمينيوم الأبيض (3) واستروميريا رقيقة (2)، مع لمسة خضراء منعشة من هيدرينجا أخضر (2). ويكتمل الجمال بفاكهة مختارة بعناية: موزتين، تفاحة حمراء، حبتين مانجو، 4 حبات ليمون، 3 جوافة، وعنقود عنب يتوّج الباقة بلمسة لافتة. تنسيق فاخر يعبّر عن الذوق الرفيع، مثالي لهدية مميزة أو لمناسبة استثنائية.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\"}', '1197', 'products/101-55.png', '[\"products\\/gallery\\/101-55.png\",\"products\\/gallery\\/102-52.png\",\"products\\/gallery\\/104-46.png\",\"products\\/gallery\\/103-52.png\"]', '{\"en\":\"<p>&lt;p&gt;&lt;span lang=\\\"AR-SA\\\" dir=\\\"RTL\\\" style=\\\"font-size:14.0pt;<br />\\nline-height:107%;font-family:Tajawal;mso-fareast-font-family:Calibri;<br />\\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:<br />\\nEN-US;mso-bidi-language:AR-SA\\\"&gt;&amp;nbsp; تشكيلة رائعة من الزهور المتناسقة لإيصال ما تريد<br />\\nمن كلمات مليئة بالمشاعر الدافئة من خلال باقة&amp;nbsp;<br />\\nأنيقة تحتوي الفواكه المنعشه مع ٥ من البيبي جوري الأحمر، والجبسوفيليا وخضار اليوكاليبتوس&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;/p&gt;</p>\",\"ar\":\"<p>&lt;p&gt;&lt;span lang=\\\"AR-SA\\\" dir=\\\"RTL\\\" style=\\\"font-size:14.0pt;<br />\\nline-height:107%;font-family:Tajawal;mso-fareast-font-family:Calibri;<br />\\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:<br />\\nEN-US;mso-bidi-language:AR-SA\\\"&gt;&amp;nbsp; تشكيلة رائعة من الزهور المتناسقة لإيصال ما تريد<br />\\nمن كلمات مليئة بالمشاعر الدافئة من خلال باقة&amp;nbsp;<br />\\nأنيقة تحتوي الفواكه المنعشه مع ٥ من البيبي جوري الأحمر، والجبسوفيليا وخضار اليوكاليبتوس&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;/p&gt;</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":230,\"name\":\"\\u0628\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0641\\u0648\\u0627\\u0643\\u0647\",\"slug\":\"%d8%a8%d8%a7%d9%82%d8%a7%d8%aa-%d8%a7%d9%84%d9%81%d9%88%d8%a7%d9%83%d9%87\"}],\"tags\":[],\"wp_ar_id\":17006}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '400.00', '400.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:06', '2026-10-07 12:19:00', NULL);
