INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('70', '17034', NULL, '[6,13,14,19,22,32,50]', NULL, NULL, NULL, '{\"en\":\"G582\",\"ar\":\"G582\"}', 'g582-2', 'g582-2', '{\"en\":\"<p>تأسر هذه الباقة الأنظار بجمال ألوانها وتناسق تفاصيلها، حيث تضم 15 وردة بدرجات وردية ناعمة، مع لمسات أنيقة من كريزنتيموم بنفسجي فاتح (4)، ولمينيوم وردي فاتح (2)، وستوما وردي فاتح (3)، تتكامل جميعها مع أوراق خضراء تضيف إشراقة طبيعية جذابة. تنبض هذه الباقة بالرقي، لتكون هدية مثالية تعبّر عن مشاعر الفرح والحب بكل أناقة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\",\"ar\":\"<p>تأسر هذه الباقة الأنظار بجمال ألوانها وتناسق تفاصيلها، حيث تضم 15 وردة بدرجات وردية ناعمة، مع لمسات أنيقة من كريزنتيموم بنفسجي فاتح (4)، ولمينيوم وردي فاتح (2)، وستوما وردي فاتح (3)، تتكامل جميعها مع أوراق خضراء تضيف إشراقة طبيعية جذابة. تنبض هذه الباقة بالرقي، لتكون هدية مثالية تعبّر عن مشاعر الفرح والحب بكل أناقة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\"}', '1183', 'products/101-82.png', '[\"products\\/gallery\\/101-82.png\",\"products\\/gallery\\/102-78.png\",\"products\\/gallery\\/103-75.png\",\"products\\/gallery\\/104-68.png\"]', '{\"en\":\"<p>تأسر هذه الباقة الأنظار بجمال ألوانها وتناسق تفاصيلها، حيث تضم 15 وردة بدرجات وردية ناعمة، مع لمسات أنيقة من كريزنتيموم بنفسجي فاتح (4)، ولمينيوم وردي فاتح (2)، وستوما وردي فاتح (3)، تتكامل جميعها مع أوراق خضراء تضيف إشراقة طبيعية جذابة. تنبض هذه الباقة بالرقي، لتكون هدية مثالية تعبّر عن مشاعر الفرح والحب بكل أناقة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 55 سم.