INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('78', '17082', NULL, '[6,13,19,22,26,32,44]', NULL, NULL, NULL, '{\"en\":\"G493\",\"ar\":\"G493\"}', 'g493-2', 'g493-2', '{\"en\":\"<p>باقة ورود مميزة تجمع بين الجمال والنقاء، تتكون من 5 قطع من زهور الليليوم الأبيض الرائعة و3 قطع من زهور اللبيديوم الخضراء. تمتاز الباقة بتنسيق عصري وأنيق، مع تغليف مميز باللون الأخضر يضيف لمسة من الرقي والانتعاش. تعتبر هذه الباقة المثالية لأي مناسبة، حيث تضفي جوًا من الفخامة والهدوء. مع لمسة نهائية من الشريط الأبيض، ستكون هذه الباقة الخيار الأمثل للتعبير عن التقدير والاحتفاء.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\",\"ar\":\"<p>باقة ورود مميزة تجمع بين الجمال والنقاء، تتكون من 5 قطع من زهور الليليوم الأبيض الرائعة و3 قطع من زهور اللبيديوم الخضراء. تمتاز الباقة بتنسيق عصري وأنيق، مع تغليف مميز باللون الأخضر يضيف لمسة من الرقي والانتعاش. تعتبر هذه الباقة المثالية لأي مناسبة، حيث تضفي جوًا من الفخامة والهدوء. مع لمسة نهائية من الشريط الأبيض، ستكون هذه الباقة الخيار الأمثل للتعبير عن التقدير والاحتفاء.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\"}', '1156', 'products/1-8.png', '[\"products\\/gallery\\/1-8.png\",\"products\\/gallery\\/2-38.png\",\"products\\/gallery\\/3-9.png\",\"products\\/gallery\\/4-10.png\"]', '{\"en\":\"<p>باقة ورود مميزة تجمع بين الجمال والنقاء، تتكون من 5 قطع من زهور الليليوم الأبيض الرائعة و3 قطع من زهور اللبيديوم الخضراء. تمتاز الباقة بتنسيق عصري وأنيق، مع تغليف مميز باللون الأخضر يضيف لمسة من الرقي والانتعاش. تعتبر هذه الباقة المثالية لأي مناسبة، حيث تضفي جوًا من ال