INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('79', '17084', NULL, '[6,11,19,24,32,48]', NULL, NULL, NULL, '{\"en\":\"G492\",\"ar\":\"G492\"}', 'g492-2', 'g492-2', '{\"en\":\"<p>أضف لمسة من الأناقة والرقي إلى يومك مع باقة بيبي أوركيد بنفسجي الفاخرة. تجمع هذه الباقة الساحرة بين درجات البنفسجي المبهجة والأخضر الحيوي لتمنحك إحساساً بالانتعاش والجمال الطبيعي. مغلّفة بورق أنيق ومربوطة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الذوق الرفيع والمشاعر الراقية في كل مناسبة.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\",\"ar\":\"<p>أضف لمسة من الأناقة والرقي إلى يومك مع باقة بيبي أوركيد بنفسجي الفاخرة. تجمع هذه الباقة الساحرة بين درجات البنفسجي المبهجة والأخضر الحيوي لتمنحك إحساساً بالانتعاش والجمال الطبيعي. مغلّفة بورق أنيق ومربوطة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الذوق الرفيع والمشاعر الراقية في كل مناسبة.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\"}', '1155', 'products/101-61.png', '[\"products\\/gallery\\/101-61.png\",\"products\\/gallery\\/102-57.png\",\"products\\/gallery\\/103-56.png\",\"products\\/gallery\\/104-51.png\",\"products\\/gallery\\/105-34.png\"]', '{\"en\":\"<p>أضف لمسة من الأناقة والرقي إلى يومك مع باقة بيبي أوركيد بنفسجي الفاخرة. تجمع هذه الباقة الساحرة بين درجات البنفسجي المبهجة والأخضر الحيوي لتمنحك إحساساً بالانتعاش والجمال الطبيعي. مغلّفة بورق أنيق ومربوطة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الذوق الرفيع والمشاعر الراقية في كل مناسبة.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\",\"ar\":\"<p>أضف لمسة من الأناقة وال