INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('80', '17088', NULL, '[3,6,14,19,20,26,32]', NULL, NULL, NULL, '{\"en\":\"G490\",\"ar\":\"G490\"}', 'g490-2', 'g490-2', '{\"en\":\"<p>تألقي بأجمل لحظاتك مع هذا الباقة الرائعة من ورد الروز المزدوج بتدرجات اللون الوردي، المكونة من 20 وردة روز فاخرة، تنبض بالجمال والرقة. تزينها 5 قطع من اللبيديوم الأخضر لإضافة لمسة طبيعية وملمس أنيق. تتميز هذه الباقة بتنسيق مذهل يضفي على كل مناسبة سحرًا خاصًا، سواء كان عيد ميلاد، أو ذكرى مميزة، أو حتى هدية تعبر عن مشاعرك. مع ربطتها الوردية الفاخرة، تعد هذه الباقة الخيار المثالي للتعبير عن الحب والجمال.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\",\"ar\":\"<p>تألقي بأجمل لحظاتك مع هذا الباقة الرائعة من ورد الروز المزدوج بتدرجات اللون الوردي، المكونة من 20 وردة روز فاخرة، تنبض بالجمال والرقة. تزينها 5 قطع من اللبيديوم الأخضر لإضافة لمسة طبيعية وملمس أنيق. تتميز هذه الباقة بتنسيق مذهل يضفي على كل مناسبة سحرًا خاصًا، سواء كان عيد ميلاد، أو ذكرى مميزة، أو حتى هدية تعبر عن مشاعرك. مع ربطتها الوردية الفاخرة، تعد هذه الباقة الخيار المثالي للتعبير عن الحب والجمال.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\"}', '1153', 'products/1-3.png', '[\"products\\/gallery\\/1-3.png\",\"products\\/gallery\\/2-5.png\",\"products\\/gallery\\/3-4.png\",\"products\\/gallery\\/4-5.png\",\"products\\/gallery\\/5-5.png\"]', '{\"en\":\"<p>تألقي بأجمل لحظاتك مع هذا الباقة الرائعة من ورد الروز المزدوج بتدرجات اللون الوردي، المكونة من 20 وردة روز فاخرة، تنبض بالجمال والرقة. تزينها 5 قطع من اللبيديوم الأخضر لإضافة لمسة طبيعي