INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('91', '17140', NULL, '[3,6,14,19,32]', NULL, NULL, NULL, '{\"en\":\"G463\",\"ar\":\"G463\"}', 'g463-2', 'g463-2', '{\"en\":\"<p>أضف لمسة من الأناقة والرقي إلى يومك مع هذا البوكيه الساحر الذي يجمع بين روعة الهايدرينجا الأبيض ولمسة الماثيولا البنفسجية الغامقة التي تبعث على الهدوء والجمال. تتناغم ورود الروز الوردي الفاتح برقتها مع اللمينيوم الوردي وخضار الأوراق الطبيعية لتمنحك تنسيقًا متكاملًا يفيض بالأنوثة والجاذبية. اختيار مثالي للتعبير عن المشاعر الرقيقة أو لتزيين المناسبات الخاصة بأجواء من الفخامة والتميز.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\",\"ar\":\"<p>أضف لمسة من الأناقة والرقي إلى يومك مع هذا البوكيه الساحر الذي يجمع بين روعة الهايدرينجا الأبيض ولمسة الماثيولا البنفسجية الغامقة التي تبعث على الهدوء والجمال. تتناغم ورود الروز الوردي الفاتح برقتها مع اللمينيوم الوردي وخضار الأوراق الطبيعية لتمنحك تنسيقًا متكاملًا يفيض بالأنوثة والجاذبية. اختيار مثالي للتعبير عن المشاعر الرقيقة أو لتزيين المناسبات الخاصة بأجواء من الفخامة والتميز.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\"}', '1126', 'products/101-59.png', '[\"products\\/gallery\\/101-59.png\",\"products\\/gallery\\/102-55.png\",\"products\\/gallery\\/103-54.png\",\"products\\/gallery\\/104-49.png\",\"products\\/gallery\\/105-32.png\"]', '{\"en\":\"<p>أضف لمسة من الأناقة والرقي إلى يومك مع هذا البوكيه الساحر الذي يجمع بين روعة الهايدرينجا الأبيض ولمسة الماثيولا البنفسجية الغامقة التي تبعث على الهدوء والجمال. تتناغم ورود الروز الوردي الفاتح برقتها مع اللمينيوم ا