INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('101', '17162', NULL, '[6,19,20,22,24,32,49]', NULL, NULL, NULL, '{\"en\":\"G402\",\"ar\":\"G402\"}', 'g402-2', 'g402-2', '{\"en\":\"<p>تنسيق زهري مفعم بالحيوية والسعادة، يجمع بين الألوان المشرقة واللمسة العصرية في سلة أنيقة من الخوص الطبيعي. يضم التنسيق 25 وردة صفراء متألقة ترمز للتفاؤل والبهجة، مع 6 زهور ألستروميريا الرقيقة، و3 عيدان لبيديوم تضيف لمسة من التوازن الأخضر الطبيعي. كما يحتوي على 5 أزهار ستوما بيضاء تمنح الباقة لمسة من النقاء، و5 زهور سوليداجو الصفراء الزاهية التي تعزز الإشراقة، إلى جانب 6 كريزنتيموم أبيض يضفي امتلاءً وأناقة. يكتمل التصميم بلمسة مرحة من 5 بالونات بيضاء وصفراء تضيف روحًا احتفالية مبهجة. هذه الباقة مثالية للمناسبات السعيدة والهدايا التي تنشر الفرح والإيجابية في كل مكان.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\",\"ar\":\"<p>تنسيق زهري مفعم بالحيوية والسعادة، يجمع بين الألوان المشرقة واللمسة العصرية في سلة أنيقة من الخوص الطبيعي. يضم التنسيق 25 وردة صفراء متألقة ترمز للتفاؤل والبهجة، مع 6 زهور ألستروميريا الرقيقة، و3 عيدان لبيديوم تضيف لمسة من التوازن الأخضر الطبيعي. كما يحتوي على 5 أزهار ستوما بيضاء تمنح الباقة لمسة من النقاء، و5 زهور سوليداجو الصفراء الزاهية التي تعزز الإشراقة، إلى جانب 6 كريزنتيموم أبيض يضفي امتلاءً وأناقة. يكتمل التصميم بلمسة مرحة من 5 بالونات بيضاء وصفراء تضيف روحًا احتفالية مبهجة. هذه الباقة مثالية للمناسبات السعيدة والهدايا التي تنشر الفرح والإيجابية في كل مكان.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\"}', '1114', 'products/1-42.png', '[\"products\\/gallery\\/1-42.pn