INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('109', '17180', NULL, '[6,14,16,19,22,24,32,49]', NULL, NULL, NULL, '{\"en\":\"G145\",\"ar\":\"G145\"}', 'g145-2', 'g145-2', '{\"en\":\"<p>تمتعوا بأجمل لحظات الرفاهية مع باقة الزهور الرائعة التي تضم مزيجاً مميزاً من الورود والأوركيد. تتكون الباقة من 20 قطعة من بيبي أوركيد وردي فاتح، 20 قطعة من روز وردي فاتح، 10 قطع من بيبي روز وردي فاتح، 20 قطعة من كرنيشن وردي فاتح، و10 قطع من استروميرا أبيض، بالإضافة إلى لمسات من اللمينوم، اللبيديوم، والخضار الطبيعي لتضيف لمسة من الأناقة والجمال في أي مناسبة. هذه الباقة مثالية لتزيين منزلك أو تقديمها كهدية تعبّر عن الحب والاهتمام.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 75 سم.</p>\",\"ar\":\"<p>تمتعوا بأجمل لحظات الرفاهية مع باقة الزهور الرائعة التي تضم مزيجاً مميزاً من الورود والأوركيد. تتكون الباقة من 20 قطعة من بيبي أوركيد وردي فاتح، 20 قطعة من روز وردي فاتح، 10 قطع من بيبي روز وردي فاتح، 20 قطعة من كرنيشن وردي فاتح، و10 قطع من استروميرا أبيض، بالإضافة إلى لمسات من اللمينوم، اللبيديوم، والخضار الطبيعي لتضيف لمسة من الأناقة والجمال في أي مناسبة. هذه الباقة مثالية لتزيين منزلك أو تقديمها كهدية تعبّر عن الحب والاهتمام.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 75 سم.</p>\"}', '1104', 'products/1-10.png', '[\"products\\/gallery\\/1-10.png\",\"products\\/gallery\\/2-12.png\",\"products\\/gallery\\/3-11.png\"]', '{\"en\":\"<p>تمتعوا بأجمل لحظات الرفاهية مع باقة الزهور الرائعة التي تضم مزيجاً مميزاً من الورود والأوركيد. تتكون الباقة من 20 قطعة من بيبي أوركيد وردي فاتح، 20 قطعة من روز وردي فاتح، 10 قطع من بيبي 