INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('112', '17186', NULL, '[6,14,19,20,22,32,50]', NULL, NULL, NULL, '{\"en\":\"G132\",\"ar\":\"G132\"}', 'g132-2', 'g132-2', '{\"en\":\"<p>تنسيق زهري فاخر يجمع بين درجات اللون الوردي بتناسقٍ مفعم بالجمال والذوق الرفيع. يضم 8 روز وردية بتدرجات مختلفة، و3 زهور ليليوم وردية وبيضاء تضفي لمسة فاخرة، مع 5 زهور ماثيولا وردية عطرة، و3 بيبي روز وردية فاتحة تضفي نعومة خاصة. يتكامل التنسيق بزهور استوما وردية فاتحة وواكس بنفسجي داكن و5 كريزنتيموم بنفسجية فاتحة، مع خضار لتتناغم جميعها بحيوية متكاملة. اختيار مثالي للتعبير عن التقدير، الفرح، أو للاحتفاء بكل لحظة مميزة.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>تنسيق زهري فاخر يجمع بين درجات اللون الوردي بتناسقٍ مفعم بالجمال والذوق الرفيع. يضم 8 روز وردية بتدرجات مختلفة، و3 زهور ليليوم وردية وبيضاء تضفي لمسة فاخرة، مع 5 زهور ماثيولا وردية عطرة، و3 بيبي روز وردية فاتحة تضفي نعومة خاصة. يتكامل التنسيق بزهور استوما وردية فاتحة وواكس بنفسجي داكن و5 كريزنتيموم بنفسجية فاتحة، مع خضار لتتناغم جميعها بحيوية متكاملة. اختيار مثالي للتعبير عن التقدير، الفرح، أو للاحتفاء بكل لحظة مميزة.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '1101', 'products/1-23.png', '[\"products\\/gallery\\/1-23.png\",\"products\\/gallery\\/2-25.png\",\"products\\/gallery\\/3-24.png\",\"products\\/gallery\\/4-22.png\"]', '{\"en\":\"<p>تنسيق زهري فاخر يجمع بين درجات اللون الوردي بتناسقٍ مفعم بالجمال والذوق الرفيع. يضم 8 روز وردية بتدرجات مختلفة، و3 زهور ليليوم وردية وبيضاء تضفي لمسة فاخرة، مع 5 زهور ماثيولا ور