INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('120', '17202', NULL, '[6,14,19,32]', NULL, NULL, NULL, '{\"en\":\"G046\",\"ar\":\"G046\"}', 'g046-2', 'g046-2', '{\"en\":\"<p>أضف لمسة من الأناقة والرقي إلى أي مناسبة مع باقة &#8220;الليليوم والروز الوردي&#8221; الساحرة. تجمع هذه التشكيلة بين 7 زهور ليليوم وردية فخمة و12 روز وردية فاتحة تعبّر عن النعومة والرومانسية، تتناغم معها 3 فروع من الليمنيوم الوردي التي تضيف لمسة من الخفة والجمال الطبيعي. تأتي الباقة مرتّبة بعناية في فازة زجاجية أنيقة ومزيّنة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الحب، الامتنان، أو التهنئة بأسلوب راقٍ ولا يُنسى.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\",\"ar\":\"<p>أضف لمسة من الأناقة والرقي إلى أي مناسبة مع باقة &#8220;الليليوم والروز الوردي&#8221; الساحرة. تجمع هذه التشكيلة بين 7 زهور ليليوم وردية فخمة و12 روز وردية فاتحة تعبّر عن النعومة والرومانسية، تتناغم معها 3 فروع من الليمنيوم الوردي التي تضيف لمسة من الخفة والجمال الطبيعي. تأتي الباقة مرتّبة بعناية في فازة زجاجية أنيقة ومزيّنة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الحب، الامتنان، أو التهنئة بأسلوب راقٍ ولا يُنسى.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\"}', '1092', 'products/01-2.png', '[\"products\\/gallery\\/01-2.png\",\"products\\/gallery\\/2-44.png\",\"products\\/gallery\\/3-42.png\",\"products\\/gallery\\/4-39.png\",\"products\\/gallery\\/5-21.png\"]', '{\"en\":\"<p>أضف لمسة من الأناقة والرقي إلى أي مناسبة مع باقة &#8220;الليليوم والروز الوردي&#8221; الساحرة. تجمع هذه التشكيلة بين 7 زهور ليليوم وردية فخمة و12 روز وردية فاتحة تعبّر عن النعومة والرومانسية، تتناغم معها 3 فروع من الليمنيوم الوردي التي تضيف لمسة من الخفة والجمال الطبيعي. تأتي الباقة مرتّبة بعناية في فازة زجاجية أنيقة ومزيّنة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الحب، الامتنان، أو التهنئة بأسلوب راقٍ ولا يُنسى.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\",\"ar\":\"<p>أضف لمسة من الأناقة والرقي إلى أي مناسبة مع باقة &#8220;الليليوم والروز الوردي&#8221; الساحرة. تجمع هذه التشكيلة بين 7 زهور ليليوم وردية فخمة و12 روز وردية فاتحة تعبّر عن النعومة والرومانسية، تتناغم معها 3 فروع من الليمنيوم الوردي التي تضيف لمسة من الخفة والجمال الطبيعي. تأتي الباقة مرتّبة بعناية في فازة زجاجية أنيقة ومزيّنة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الحب، الامتنان، أو التهنئة بأسلوب راقٍ ولا يُنسى.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":208,\"name\":\"\\u0644\\u0644\\u0623\\u0645\",\"slug\":\"%d9%84%d9%84%d8%a3%d9%85\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"},{\"id\":203,\"name\":\"\\u0648\\u0631\\u062f\\u064a\",\"slug\":\"%d9%88%d8%b1%d8%af%d9%8a\"}],\"tags\":[],\"wp_ar_id\":17202}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '380.00', '380.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:17', '2026-10-07 12:24:37', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('121', '17206', NULL, '[21,25,32]', NULL, NULL, NULL, '{\"en\":\"G172\",\"ar\":\"G172\"}', 'g172-2', 'g172-2', '{\"en\":\"<p>تتميز هذه التشكيلة الفاخرة التي تضم 80 حبه من الجوري الاحمر بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. مع تنسيق متقن 10حبه من الكريزنتيموم الابيض يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.</p>\\n<p>الارتفاع حوالي 75 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\",\"ar\":\"<p>تتميز هذه التشكيلة الفاخرة التي تضم 80 حبه من الجوري الاحمر بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. مع تنسيق متقن 10حبه من الكريزنتيموم الابيض يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.</p>\\n<p>الارتفاع حوالي 75 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\"}', '1090', 'products/101-76.png', '[\"products\\/gallery\\/101-76.png\",\"products\\/gallery\\/102-71.png\",\"products\\/gallery\\/103-69.png\"]', '{\"en\":\"<p>تتميز هذه التشكيلة الفاخرة التي تضم 80 حبه من الجوري الاحمر بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. مع تنسيق متقن 10حبه من الكريزنتيموم الابيض يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.</p>\\n<p>الارت