INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('144', '17310', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G620\",\"ar\":\"G620\"}', 'g620-2', 'g620-2', '{\"en\":\"<p>لذة طعم الفواكه وجمال الأزهار تجلب الرغبة بالدفء وتنعش الحواس لترجع الأحاسيس الصادقة إلى الحياة. باقة فواكه رائعة مناسبة كهدية في جميع المواسم.</p>\\n<p>تحتوي على التوليب الأحمر والاسترومريا والبيبي جوري والاستوما الأبيض مع الليمينوم الأبيض بالإضافة الى التوليب التي يعطيه إحساس بالسعادة , مع الخضارات الرائعة التي تدمج بين الورد والفواكه</p>\\n<p>والمحتوية من التفاح الأحمر والرمان، البرتقال، الفراولة! املأ حياتهم بلحظات لا تُنسى</p>\\n<p>الارتفاع حوالي45سم</p>\\n<p>العرض حوالي 55سم</p>\",\"ar\":\"<p>لذة طعم الفواكه وجمال الأزهار تجلب الرغبة بالدفء وتنعش الحواس لترجع الأحاسيس الصادقة إلى الحياة. باقة فواكه رائعة مناسبة كهدية في جميع المواسم.</p>\\n<p>تحتوي على التوليب الأحمر والاسترومريا والبيبي جوري والاستوما الأبيض مع الليمينوم الأبيض بالإضافة الى التوليب التي يعطيه إحساس بالسعادة , مع الخضارات الرائعة التي تدمج بين الورد والفواكه</p>\\n<p>والمحتوية من التفاح الأحمر والرمان، البرتقال، الفراولة! املأ حياتهم بلحظات لا تُنسى</p>\\n<p>الارتفاع حوالي45سم</p>\\n<p>العرض حوالي 55سم</p>\"}', '980', 'products/102-front-png.png', '[\"products\\/gallery\\/102-front-png.png\",\"products\\/gallery\\/104-40.png\",\"products\\/gallery\\/103-47.png\",\"products\\/gallery\\/101-49.png\"]', '{\"en\":\"<p>لذة طعم الفواكه وجمال الأزهار تجلب الرغبة بالدفء وتنعش الحواس لترجع الأحاسيس الصادقة إلى الحياة. باقة فواكه رائعة مناسبة كهدية في جميع المواسم. تحتوي على التوليب الأحمر والاسترومريا والبيبي جوري والاستوما الأبيض مع الليمينوم الأبيض بالإضافة الى التوليب التي يعطيه إحساس بالسعادة , مع الخضارات الرائعة التي تدمج بين الورد والفواكه والمحتوية من التفاح الأحمر والرمان، البرتقال، الفراولة! املأ حياتهم بلحظات لا تُنسى</p>\",\"ar\":\"<p>لذة طعم الفواكه وجمال الأزهار تجلب الرغبة بالدفء وتنعش الحواس لترجع الأحاسيس الصادقة إلى الحياة. باقة فواكه رائعة مناسبة كهدية في جميع المواسم. تحتوي على التوليب الأحمر والاسترومريا والبيبي جوري والاستوما الأبيض مع الليمينوم الأبيض بالإضافة الى التوليب التي يعطيه إحساس بالسعادة , مع الخضارات الرائعة التي تدمج بين الورد والفواكه والمحتوية من التفاح الأحمر والرمان، البرتقال، الفراولة! املأ حياتهم بلحظات لا تُنسى</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":230,\"name\":\"\\u0628\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0641\\u0648\\u0627\\u0643\\u0647\",\"slug\":\"%d8%a8%d8%a7%d9%82%d8%a7%d8%aa-%d8%a7%d9%84%d9%81%d9%88%d8%a7%d9%83%d9%87\"}],\"tags\":[],\"wp_ar_id\":17310}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '460.00', '460.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:19', '2026-10-07 12:26:44', NULL);
