INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('149', '17324', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G615\",\"ar\":\"G615\"}', 'g615-2', 'g615-2', '{\"en\":\"<p>املأ حياتهم بلحظات لا تُنسى من خلال إهداء هذه الفازة النابضة بالحياة التي تنبض بالحيوية والجمال الطبيعي! تنسيق فاخر يجمع بين فخامة الزهور ونضارة الفواكه، يتوسطه أناناس طازج محاط بعناقيد من العنب الأحمر، وتفاح أحمر وأخضر يضفيان لمسة من التوازن اللوني، مع 12 حبة برتقال وفراولة شهية تملأ الباقة بالحيوية. وتزهر الباقة بـ5 زهور توليب حمراء أنيقة، وحبتان من الجربيرا البيضاء التي تنبض بالنقاء، مع لمسات ناعمة من الواكس الأبيض وحبتان من اللبيديوم، محاطة بخضار طبيعي يعزز من جاذبية التنسيق. مثالية للإهداء في المناسبات الراقية أو لتزيين أجواءك بلمسة من الإبداع والجمال الطبيعي.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\",\"ar\":\"<p>املأ حياتهم بلحظات لا تُنسى من خلال إهداء هذه الفازة النابضة بالحياة التي تنبض بالحيوية والجمال الطبيعي! تنسيق فاخر يجمع بين فخامة الزهور ونضارة الفواكه، يتوسطه أناناس طازج محاط بعناقيد من العنب الأحمر، وتفاح أحمر وأخضر يضفيان لمسة من التوازن اللوني، مع 12 حبة برتقال وفراولة شهية تملأ الباقة بالحيوية. وتزهر الباقة بـ5 زهور توليب حمراء أنيقة، وحبتان من الجربيرا البيضاء التي تنبض بالنقاء، مع لمسات ناعمة من الواكس الأبيض وحبتان من اللبيديوم، محاطة بخضار طبيعي يعزز من جاذبية التنسيق. مثالية للإهداء في المناسبات الراقية أو لتزيين أجواءك بلمسة من الإبداع والجمال الطبيعي.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\"}', '944', 'products/102-53.png', '[\"products\\/gallery\\/102-53.png\",\"products