INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('150', '17326', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G613\",\"ar\":\"G613\"}', 'g613-2', 'g613-2', '{\"en\":\"<p>تنسيق أنيق يجمع بين نضارة الفاكهة وجمال الزهور في تصميم عصري فاخر داخل فازة شفافة مزينة بورود وردية. يحتوي على فراولة طازجة بتوزيع متناسق في الأعلى، وتفاح أخضر وأحمر، ورمان، وكمثرى، مع لمسات زهرية من الكريزنتيموم البنفسجي والكيرميت الأخضر وجبسوفيليا البيضاء تضيف نعومة وأناقة، إلى جانب خضار تنسيقي يمنح مظهرًا طبيعيًا متكاملًا. تصميم مثالي يجمع بين الحيوية والفخامة، مناسب للهدايا الراقية والمناسبات المميزة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 25 سم</p>\",\"ar\":\"<p>تنسيق أنيق يجمع بين نضارة الفاكهة وجمال الزهور في تصميم عصري فاخر داخل فازة شفافة مزينة بورود وردية. يحتوي على فراولة طازجة بتوزيع متناسق في الأعلى، وتفاح أخضر وأحمر، ورمان، وكمثرى، مع لمسات زهرية من الكريزنتيموم البنفسجي والكيرميت الأخضر وجبسوفيليا البيضاء تضيف نعومة وأناقة، إلى جانب خضار تنسيقي يمنح مظهرًا طبيعيًا متكاملًا. تصميم مثالي يجمع بين الحيوية والفخامة، مناسب للهدايا الراقية والمناسبات المميزة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 25 سم</p>\"}', '943', 'products/103png-front.png', '[\"products\\/gallery\\/103png-front.png\",\"products\\/gallery\\/104-44.png\",\"products\\/gallery\\/102-50.png\",\"products\\/gallery\\/101-53.png\"]', '{\"en\":\"<p>تنسيق أنيق يجمع بين نضارة الفاكهة وجمال الزهور في تصميم عصري فاخر داخل فازة شفافة مزينة بورود وردية. يحتوي على فراولة طازجة بتوزيع متناسق في الأعلى، وتفاح أخضر وأحمر، ورمان، وكمثرى، مع لمسات زهرية من الكريزنتيموم البنفسجي والكيرميت الأخضر وجبسوفيليا البيضاء تضيف نعومة وأناقة، إلى جانب خضار تنسيقي يمنح مظهرًا طبيعيًا متكاملًا. تصميم مثالي يجمع بين الحيوية والفخامة، مناسب للهدايا الراقية والمناسبات المميزة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 25 سم</p>\",\"ar\":\"<p>تنسيق أنيق يجمع بين نضارة الفاكهة وجمال الزهور في تصميم عصري فاخر داخل فازة شفافة مزينة بورود وردية. يحتوي على فراولة طازجة بتوزيع متناسق في الأعلى، وتفاح أخضر وأحمر، ورمان، وكمثرى، مع لمسات زهرية من الكريزنتيموم البنفسجي والكيرميت الأخضر وجبسوفيليا البيضاء تضيف نعومة وأناقة، إلى جانب خضار تنسيقي يمنح مظهرًا طبيعيًا متكاملًا. تصميم مثالي يجمع بين الحيوية والفخامة، مناسب للهدايا الراقية والمناسبات المميزة.</p>\\n<p>الارتفاع حوالي 45 سم.</p>\\n<p>العرض حوالي 25 سم</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":230,\"name\":\"\\u0628\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0641\\u0648\\u0627\\u0643\\u0647\",\"slug\":\"%d8%a8%d8%a7%d9%82%d8%a7%d8%aa-%d8%a7%d9%84%d9%81%d9%88%d8%a7%d9%83%d9%87\"}],\"tags\":[],\"wp_ar_id\":17326}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '220.00', '220.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:20', '2026-10-07 12:26:58', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('151', '17328', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G614\",\"ar\":\"G614\"}', 'g614-2', 'g614-2', '{\"en\":\"<p>املأ حياتهم بلحظات لا تُنسى من خلال إهداء هذه الباقة النابضة بالحياة بسلة فواكه وزهور بطابع ريفي فاخر، مصممة بذوق فني يجمع بين الطبيعة والنضارة، تحتوي على أناناس، ثلاث حبات برتقال كبير، حبتين من التفاح الأحمر، ثلاث حبات موز، فراولة طازجة، وعناقيد عنب أخضر، وتتزين بـ 20 وردة روز حمراء أنيقة، زهرات الجربيرا البيضاء، ثلاث حبات من الكريزنتيموم الأبيض، أربع زهرات بيضاء بيبي أوركيد، أربع زهرات واكس أبيض، وثلاثة زهرات لبيديوم ، لتمنح السلة مظهرًا متوازنًا يجمع بين الجمال والحيوية، وتناسب مختلف المناسبات كهدية راقية ومميزة.</p>\\n<p>الارتفاع حوالي40سم</p>\\n<p>العرض حوالي 35سم</p>\",\"ar\":\"<p>املأ حياتهم بلحظات لا تُنسى من خلال إهداء هذه الباقة النابضة بالحياة بسلة فواكه وزهور بطابع ريفي فاخر، مصممة بذوق فني يجمع بين الطبيعة والنضارة، تحتوي على أناناس، ثلاث حبات برتقال كبير، حبتين من التفاح الأحمر، ثلاث حبات موز، فراولة طازجة، وعناقيد عنب أخضر، وتتزين بـ 20 وردة روز حمراء أنيقة، زهرات الجربيرا البيضاء، ثلاث حبات من الكريزنتيموم الأبيض، أربع زهرات بيضاء بيبي أوركيد، أربع زهرات واكس أبيض، وثلاثة زهرات لبيديوم ، لتمنح السلة مظهرًا متوازنًا يجمع بين الجمال والحيوية، وتناسب مختلف المناسبات كهدية راقية ومميزة.</p>\\n<p>الارتفاع حوالي40سم</p>\\n<p>العرض حوالي 35سم</p>\"}', '901', 'products/103-front-1.png', '[\"products\\/gallery\\/103-front-1.png\",\"products\\/gallery\\/101-51.png\",\"products\\/gallery\\/1012.png\",\"products\\/gallery\\/102-47.png\"]', '{\"en\":\"<p>عبّر عن حبك بهدية من الفواكه الطبيعية واصنع ألطف الذكريات في ذهن من أحببت مع مع أجمل الأزهار المُنعشة للروح.<br />\\nتحتوي على الأنواع التالية من الزهور: الروز الأبيض، الجيبسوفيليا البيضاء، خضارات الإستيل، مجموعة من الخضارات الطبيعية.<br />\\nتحتوي على الأنواع التالية من الفواكه: الليمون، البرتقال.<br />\\nالارتفاع حوالي 40 سم إلى 50 سم.<br />\\nالعرض حوالي 35 سم إلى 25 سم.</p>\",\"ar\":\"<p>عبّر عن حبك بهدية من الفواكه الطبيعية واصنع ألطف الذكريات في ذهن من أحببت مع مع أجمل الأزهار المُنعشة للروح.<br />\\nتحتوي على الأنواع التالية من الزهور: الروز الأبيض، الجيبسوفيليا البيضاء، خضارات الإستيل، مجموعة من الخضارات الطبيعية.<br />\\nتحتوي على الأنواع التالية من الفواكه: الليمون، البرتقال.<br />\\nالارتفاع حوالي 40 سم إلى 50 سم.<br />\\nالعرض حوالي 35 سم إلى 25 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":230,\"name\":\"\\u0628\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0641\\u0648\\u0627\\u0643\\u0647\",\"slug\":\"%d8%a8%d8%a7%d9%82%d8%a7%d8%aa-%d8%a7%d9%84%d9%81%d9%88%d8%a7%d9%83%d9%87\"}],\"tags\":[],\"wp_ar_id\":17328}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '460.00', '460.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:25', '2026-10-07 12:27:05', NULL);
