INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('155', '17342', NULL, '[25,32]', NULL, NULL, NULL, '{\"en\":\"G449\",\"ar\":\"G449\"}', 'g449-2', 'g449-2', '{\"en\":\"<p>عبّر عن حبك بعبق الزهور المُنعشة للروح واصنع أجمل اللحظات في حياة أحبتك من خلال باقة مكونة من الهيدرينجيا باللون الأخضر الفاتح والوردي مع الليليوم باللون أبيض والوردي، بالإضافة إلى زهور الفيرونيكا والإستوما الوردية الجميلة مع زهور الديكو والواكس فلاور باللون الأبيض. انعش حواس أحبتك بأجمل الزهور كالهيدرينجيا والكالا باللون الأبيض مع الكيرميت الأخضر وزهور الإيستاتيس والروز باللون الأبيض والوردي الرائع، بالإضافة إلى الكريزنتيموم باللون الأبيض والبنفسجي الآسر للقلب.</p>\\n<p>الارتفاع حوالي 40 سم إلى 50 سم.</p>\\n<p>العرض حوالي 40 سم إلى 50 سم.</p>\",\"ar\":\"<p>عبّر عن حبك بعبق الزهور المُنعشة للروح واصنع أجمل اللحظات في حياة أحبتك من خلال باقة مكونة من الهيدرينجيا باللون الأخضر الفاتح والوردي مع الليليوم باللون أبيض والوردي، بالإضافة إلى زهور الفيرونيكا والإستوما الوردية الجميلة مع زهور الديكو والواكس فلاور باللون الأبيض. انعش حواس أحبتك بأجمل الزهور كالهيدرينجيا والكالا باللون الأبيض مع الكيرميت الأخضر وزهور الإيستاتيس والروز باللون الأبيض والوردي الرائع، بالإضافة إلى الكريزنتيموم باللون الأبيض والبنفسجي الآسر للقلب.</p>\\n<p>الارتفاع حوالي 40 سم إلى 50 سم.</p>\\n<p>العرض حوالي 40 سم إلى 50 سم.</p>\"}', '729', 'products/g44920jeddah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/g44920jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/g44920send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g44920send20flow