INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('156', '17344', NULL, '[13,25,32,44]', NULL, NULL, NULL, '{\"en\":\"G448\",\"ar\":\"G448\"}', 'g448-2', 'g448-2', '{\"en\":\"<p>هدية مُغلفة بحب لتُرسل أجمل المشاعر وأصدقها. مجموعة من أجمل الأزهار المختارة بعناية مثل السمبيديوم والفيلينوبسيس الأبيض مع زهور الهيدرينجيا باللونين الأخضر والأبيض. ارسم البسمة على وجوه أحبتك وكن السبب وراء سعادتهم من خلال باقة تحتوي على التوليب والبيبي أوركيد باللون الأبيض مع البيبي روز والإستوما البيضاء، بالإضافة إلى الليليوم والواكس فلاور الأبيض مع خضارات البامبو الملتوية وخضارات الإستيل الرائعة.عبّر عن حبك بهدية من الزهور الطبيعية واصنع أجمل الذكريات في ذهن من أحببت.</p>\\n<p>الارتفاع حوالي 75 سم إلى 85 سم.</p>\\n<p>العرض حوالي 35 سم إلى 45 سم.</p>\",\"ar\":\"<p>هدية مُغلفة بحب لتُرسل أجمل المشاعر وأصدقها. مجموعة من أجمل الأزهار المختارة بعناية مثل السمبيديوم والفيلينوبسيس الأبيض مع زهور الهيدرينجيا باللونين الأخضر والأبيض. ارسم البسمة على وجوه أحبتك وكن السبب وراء سعادتهم من خلال باقة تحتوي على التوليب والبيبي أوركيد باللون الأبيض مع البيبي روز والإستوما البيضاء، بالإضافة إلى الليليوم والواكس فلاور الأبيض مع خضارات البامبو الملتوية وخضارات الإستيل الرائعة.عبّر عن حبك بهدية من الزهور الطبيعية واصنع أجمل الذكريات في ذهن من أحببت.</p>\\n<p>الارتفاع حوالي 75 سم إلى 85 سم.</p>\\n<p>العرض حوالي 35 سم إلى 45 سم.</p>\"}', '728', 'products/g44820jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/g44820jeddah20flowers20delivery-600x600-1.jpg\"]', '{\"en\":\"<p>هدية مُغلفة بحب لتُرسل أجمل المشاعر وأصدقها. مجموعة من أجمل الأزها