INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('160', '17356', NULL, '[3,4,6,14,19,20,32,48,50]', NULL, NULL, NULL, '{\"en\":\"G442\",\"ar\":\"G442\"}', 'g442-2', 'g442-2', '{\"en\":\"<p>استمتعوا بتشكيلة فاخرة من الأزهار التي تجمع بين الجمال والرقة في تنسيق واحد. يتضمن الباقة 8 قطع من زهور الليليوم الأبيض التي تتميز بأناقتها، إلى جانب 5 قطع من زهور استروميرا البيضاء التي تضفي لمسة من الانتعاش. وتكتمل هذه الباقة بخضارٍ مميز يضيف إلى التنسيق رونقًا طبيعيًا. مع لمسة من الرباط الزخرفي الجميل، هذه الباقة هي الخيار المثالي لإهداء شخص عزيز أو لتزيين أي مكان بأجواء من الفخامة والراحة.</p>\\n<p>الارتفاع حوالي 75 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\",\"ar\":\"<p>استمتعوا بتشكيلة فاخرة من الأزهار التي تجمع بين الجمال والرقة في تنسيق واحد. يتضمن الباقة 8 قطع من زهور الليليوم الأبيض التي تتميز بأناقتها، إلى جانب 5 قطع من زهور استروميرا البيضاء التي تضفي لمسة من الانتعاش. وتكتمل هذه الباقة بخضارٍ مميز يضيف إلى التنسيق رونقًا طبيعيًا. مع لمسة من الرباط الزخرفي الجميل، هذه الباقة هي الخيار المثالي لإهداء شخص عزيز أو لتزيين أي مكان بأجواء من الفخامة والراحة.</p>\\n<p>الارتفاع حوالي 75 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\"}', '722', 'products/01-3.png', '[\"products\\/gallery\\/01-3.png\",\"products\\/gallery\\/2-45.png\",\"products\\/gallery\\/3-43.png\",\"products\\/gallery\\/4-40.png\"]', '{\"en\":\"<p>ارسل أجمل الكلمات بأحرفٍ من زهر وعبّر اشتياقك من خلال باقة نابضة بالحياة في مزهرية تحتوي على زهور الليليوم الوردي مع خضارات الإستيل لإضافة لمسة من الجمال. أظهر لهم حبك بهدية مستوحاة من الطبيعة. الارتفاع حوالي 40 سم إلى 50 سم. العرض حوالي 30 سم إلى 40 سم.</p>\",\"ar\":\"<p>ارسل أجمل الكلمات بأحرفٍ من زهر وعبّر اشتياقك من خلال باقة نابضة بالحياة في مزهرية تحتوي على زهور الليليوم الوردي مع خضارات الإستيل لإضافة لمسة من الجمال. أظهر لهم حبك بهدية مستوحاة من الطبيعة. الارتفاع حوالي 40 سم إلى 50 سم. العرض حوالي 30 سم إلى 40 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":193,\"name\":\"\\u0627\\u0639\\u062a\\u0630\\u0627\\u0631\",\"slug\":\"%d8%a7%d8%b9%d8%aa%d8%b0%d8%a7%d8%b1\"},{\"id\":241,\"name\":\"\\u0627\\u0643\\u062a\\u0648\\u0628\\u0631 \\u0627\\u0644\\u0648\\u0631\\u062f\\u064a\",\"slug\":\"%d8%a7%d9%83%d8%aa%d9%88%d8%a8%d8%b1-%d8%a7%d9%84%d9%88%d8%b1%d8%af%d9%8a\"},{\"id\":239,\"name\":\"\\u0627\\u0644\\u0639\\u064a\\u062f\",\"slug\":\"%d8%a7%d9%84%d8%b9%d9%8a%d8%af\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug\":\"%d8%b9%d9%8a%d8%af-%d9%85%d9%8a%d9%84%d8%a7%d8%af\"},{\"id\":208,\"name\":\"\\u0644\\u0644\\u0623\\u0645\",\"slug\":\"%d9%84%d9%84%d8%a3%d9%85\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"},{\"id\":192,\"name\":\"\\u0645\\u0648\\u0644\\u0648\\u062f\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629\",\"slug\":\"%d9%85%d9%88%d9%84%d9%88%d8%af%d8%a9-%d8%ac%d8%af%d9%8a%d8%af%d8%a9\"},{\"id\":203,\"name\":\"\\u0648\\u0631\\u062f\\u064a\",\"slug\":\"%d9%88%d8%b1%d8%af%d9%8a\"}],\"tags\":[],\"wp_ar_id\":17356}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '380.00', '380.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:25', '2026-10-07 12:27:36', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('161', '17358', NULL, '[6,11,19,20,22,24,32,49]', NULL, NULL, NULL, '{\"en\":\"G441\",\"ar\":\"G441\"}', 'g441-2', 'g441-2', '{\"en\":\"<p>عبّر عن مشاعرك بألطف الكلمات واصنع لحظات جميلة في حياة من تحب من خلال باقة في مزهرية ذات تصميم فني تحتوي على الروز والإيستوما باللون البنفسجي الداكن مع الإيستاتيس والفيرونيكا باللون البنفسجي. ارسل كل أحاسيسك الدفينة مع أفضل أنواع الزهور مثل التوليب الوردي والسوليداجو والواكس فلاور البنفسجي والهايبركم الأخضر مع خضارات البامبو الملتوية لإضافة لمسة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 30 سم إلى 40 سم.</p>\\n<p>العرض حوالي 25 سم إلى 35 سم.</p>\",\"ar\":\"<p>عبّر عن مشاعرك بألطف الكلمات واصنع لحظات جميلة في حياة من تحب من خلال باقة في مزهرية ذات تصميم فني تحتوي على الروز والإيستوما باللون البنفسجي الداكن مع الإيستاتيس والفيرونيكا باللون البنفسجي. ارسل كل أحاسيسك الدفينة مع أفضل أنواع الزهور مثل التوليب الوردي والسوليداجو والواكس فلاور البنفسجي والهايبركم الأخضر مع خضارات البامبو الملتوية لإضافة لمسة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 30 سم إلى 40 سم.</p>\\n<p>العرض حوالي 25 سم إلى 35 سم.</p>\"}', '721', 'products/g44120flower20delivery20jeddah201-600x600-1.jpg', '[\"products\\/gallery\\/g44120flower20delivery20jeddah201-600x600-1.jpg\",\"products\\/gallery\\/g44120flower20delivery20jeddah202-600x600-1.jpg\",\"products\\/gallery\\/g44120flower20delivery20jeddah204-600x600-1.jpg\",\"products\\/gallery\\/g44120flower20delivery20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g441-flower-delivery-jeddah-3-600x600-1.jpg\"]', '{\"en\":\"<p>عبّر عن مشاعرك بألطف الكلمات واصنع لحظات جميلة في حياة من تحب من خلال باقة في مزهرية ذات تصميم فني تحتوي على الروز والإيستوما باللون البنفسجي الداكن مع الإيستاتيس والفيرونيكا باللون البنفسجي. ارسل كل أحاسيسك الدفينة مع أفضل أنواع الزهور مثل التوليب الوردي والسوليداجو والواكس فلاور البنفسجي والهايبركم الأخضر مع خضارات البامبو الملتوية لإضافة لمسة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 30 سم إلى 40 سم.</p>\\n<p>العرض حوالي 25 سم إلى 35 سم.</p>\",\"ar\":\"<p>عبّر عن مشاعرك بألطف الكلمات واصنع لحظات جميلة في حياة من تحب من خلال باقة في مزهرية ذات تصميم فني تحتوي على الروز والإيستوما باللون البنفسجي الداكن مع الإيستاتيس والفيرونيكا باللون البنفسجي. ارسل كل أحاسيسك الدفينة مع أفضل أنواع الزهور مثل التوليب الوردي والسوليداجو والواكس فلاور البنفسجي والهايبركم الأخضر مع خضارات البامبو الملتوية لإضافة لمسة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 30 سم إلى 40 سم.</p>\\n<p>العرض حوالي 25 سم إلى 35 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":200,\"name\":\"\\u0628\\u0646\\u0641\\u0633\\u062c\\u064a\",\"slug\":\"%d8%a8%d9%86%d9%81%d8%b3%d8%ac%d9%8a\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug\":\"%d8%b9%d9%8a%d8%af-%d9%85%d9%8a%d9%84%d8%a7%d8%af\"},{\"id\":240,\"name\":\"\\u0644\\u0644\\u0622\\u0628\",\"slug\":\"%d9%84%d9%84%d8%a2%d8%a8\"},{\"id\":208,\"name\":\"\\u0644\\u0644\\u0623\\u0645\",\"slug\":\"%d9%84%d9%84%d8%a3%d9%85\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d