INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('162', '17360', NULL, '[3,4,6,14,20,32,48]', NULL, NULL, NULL, '{\"en\":\"G440\",\"ar\":\"G440\"}', 'g440-2', 'g440-2', '{\"en\":\"<p>اكتشف هدية فريدة من نوعها تجمع بين الجمال والمذاق! ، يضم 10 وردات روز بتدرجات البنفسجي مع توليفة ساحرة من ماثيولا بنفسجي غامق ولمينيوم بنفسجي وستوما بألوان وردية وبنفسجية فاتحة، تتناغم مع لمسات الستروميريا البيضاء ولبيديوم الأخضر لتضفي لمسة من الانتعاش والجمال الطبيعي. تصميم فاخر داخل قاعدة زجاجية شفافة يعكس الأناقة في كل زاوية، مثالي للهدايا أو لتزيين المساحات بأسلوب راقٍ وناعم.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\",\"ar\":\"<p>اكتشف هدية فريدة من نوعها تجمع بين الجمال والمذاق! ، يضم 10 وردات روز بتدرجات البنفسجي مع توليفة ساحرة من ماثيولا بنفسجي غامق ولمينيوم بنفسجي وستوما بألوان وردية وبنفسجية فاتحة، تتناغم مع لمسات الستروميريا البيضاء ولبيديوم الأخضر لتضفي لمسة من الانتعاش والجمال الطبيعي. تصميم فاخر داخل قاعدة زجاجية شفافة يعكس الأناقة في كل زاوية، مثالي للهدايا أو لتزيين المساحات بأسلوب راقٍ وناعم.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\"}', '720', 'products/101-63.png', '[\"products\\/gallery\\/101-63.png\",\"products\\/gallery\\/102-59.png\",\"products\\/gallery\\/103-57.png\",\"products\\/gallery\\/104-53.png\",\"products\\/gallery\\/105-35.png\"]', '{\"en\":\"<p>اكتشف هدية فريدة من نوعها تجمع بين الجمال والمذاق! ، يضم 10 وردات روز بتدرجات البنفسجي مع توليفة ساحرة من ماثيولا بنفسجي غامق ولمينيوم بنفسجي وستوما بألوان وردية وبنفسجية فاتحة، تتناغم مع لمسات الستروميريا البيضا