INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('163', '17364', NULL, '[3,4,6,14,19,20,32,48]', NULL, NULL, NULL, '{\"en\":\"G438\",\"ar\":\"G438\"}', 'g438', 'g438', '{\"en\":\"Celebrate the most beautiful moments with your loved ones by gifting this elegant vase arrangement. This enchanting bouquet features a stunning blend of natural flowers, white and purple roses, pink lilies, and purple limonium artfully arranged with white and purple wax flowers, veronica, and white eustoma. To complete the look, the bouquet includes white chrysanthemums, white hypericum, and lush greenery such as twisted bamboo and steel grass. Every detail is thoughtfully designed to express deep emotions and affection straight from the heart.\\nThe height is approximately 25 cm to 35 cm.\\nThe width is approximately 20 cm to 30 cm.\",\"ar\":\"استمتع بأجمل اللحظات مع أحبتك وقم بإهداء باقة في مزهرية أنيقة بترتيب ساحر لأجمل الأزهار الطبيعية كالروز باللون الأبيض والبنفسجي مع الليليوم الوردي والليمونيوم البنفسجي، بالإضافة إلى الواكس فلاور باللون الأبيض والبنفسجي مع زهور الفيرونيكا والإيستوما البيضاء. امنح أحبتك كل الحب من خلال هذه الباقة الجذابة المكونة من الكريزنتيموم والهايبركم باللون الأبيض مع خضارات البامبو الملتوية وخضارات الإستيل. إنها طريقة جميلة لإظهار المشاعر التي تكنها بداخل قلبك تجاه من تحب!\\nالارتفاع حوالي 25 سم إلى 35 سم.\\nالعرض حوالي 20 سم إلى 30 سم.\"}', '718', 'products/g43820send20fower20to20jeddah-600x600-1.jpg', '[\"products\\/gallery\\/g43820send20fower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g43820send20fowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g438jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/g438-jeddah-flowers-delivery-600x600-1.jpg\"]', '{\"en\":\"Celebrate the most beautiful moments with your loved ones by gifting this elegant vase arrangement. This enchanting bouquet features a stunning blend of natural flowers, white and purple roses, pink lilies, and purple limonium artfully arranged with white and purple wax flowers, veronica, and white eustoma. To complete the look, the bouquet includes white chrysanthemums, white hypericum, and lush greenery such as twisted bamboo and steel grass. Every detail is thoughtfully designed to express deep emotions and affection straight from the heart.\\nThe height is approximately 25 cm to 35 cm.\\nThe width is approximately 20 cm to 30 cm.\",\"ar\":\"استمتع بأجمل اللحظات مع أحبتك وقم بإهداء باقة في مزهرية أنيقة بترتيب ساحر لأجمل الأزهار الطبيعية كالروز باللون الأبيض والبنفسجي مع الليليوم الوردي والليمونيوم البنفسجي، بالإضافة إلى الواكس فلاور باللون الأبيض والبنفسجي مع زهور الفيرونيكا والإيستوما البيضاء. امنح أحبتك كل الحب من خلال هذه الباقة الجذابة المكونة من الكريزنتيموم والهايبركم باللون الأبيض مع خضارات البامبو الملتوية وخضارات الإستيل. إنها طريقة جميلة لإظهار المشاعر التي تكنها بداخل قلبك تجاه من تحب!\\nالارتفاع حوالي 25 سم إلى 35 سم.\\nالعرض حوالي 20 سم إلى 30 سم.\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17364,\"wp_en_id\":91153}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:26', '2026-10-07 12:27:51', NULL);
