INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('165', '17368', NULL, '[6,11,19,20,22,24,32,50]', NULL, NULL, NULL, '{\"en\":\"G433\",\"ar\":\"G433\"}', 'g433-2', 'g433-2', '{\"en\":\"<p>ضع بداية ملونة ومشرقة في يوم من تحب مع هدية رائعة. باقة في مزهرية النابضة بالحياة مليئة بالأزهار بألوان مختلفة ومبهجة، حيث تحتوي على زهور الهيدرينجيا الوردية والروز البنفسجي مع الفيرونيكا والكريزنتيموم باللون البنفسجي، بالإضافة إلى التوليب البنفسجي الجميل مع الليمونيوم والواكس فلاور البنفسجي الرائع. انعش أحاسيسهم بعبق زهور الهايبركم الوردية والبيبي أوركيد والإيستوما باللون البنفسجي مع خضارات الإستيل وخضارات البامبو الملتوية مع خضارات الإسباراجوس الخلابة.</p>\\n<p>الارتفاع حوالي 30 سم إلى 40 سم.</p>\\n<p>العرض حوالي 25 سم إلى 35 سم.</p>\",\"ar\":\"<p>ضع بداية ملونة ومشرقة في يوم من تحب مع هدية رائعة. باقة في مزهرية النابضة بالحياة مليئة بالأزهار بألوان مختلفة ومبهجة، حيث تحتوي على زهور الهيدرينجيا الوردية والروز البنفسجي مع الفيرونيكا والكريزنتيموم باللون البنفسجي، بالإضافة إلى التوليب البنفسجي الجميل مع الليمونيوم والواكس فلاور البنفسجي الرائع. انعش أحاسيسهم بعبق زهور الهايبركم الوردية والبيبي أوركيد والإيستوما باللون البنفسجي مع خضارات الإستيل وخضارات البامبو الملتوية مع خضارات الإسباراجوس الخلابة.</p>\\n<p>الارتفاع حوالي 30 سم إلى 40 سم.</p>\\n<p>العرض حوالي 25 سم إلى 35 سم.</p>\"}', '713', 'products/g43320jeddah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/g43320jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/g43320send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g433-send-flow