INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('168', '17378', NULL, '[3,6,13,20,22,23,24,32]', NULL, NULL, NULL, '{\"en\":\"G425\",\"ar\":\"G425\"}', 'g425-2', 'g425-2', '{\"en\":\"<p>أضف لمسة من الجمال الطبيعي إلى منزلك مع هذا التشكيل الرائع من الزهور المتنوعة. يتضمن الباقة قطعاً من قطعتان من الهايدرينجا الأبيض الجميل، و5 بيبي روز الوردي الفاتح، و10 روز البنفسجي الفاتح، و10 روز أبيض، مع مزيج من الماثيولا البنفسجي الغامق 5 قطع، 3 استوما وردي فاتح، وقطعتان من الستاتس البنفسجي الغامق. إضافة إلى لمسات من اللمينيوم البنفسجي والخضار الطازج، مما يجعل هذه الباقة خياراً مثالياً للزينة أو كهدية رائعة في أي مناسبة. احصل عليها الآن لتضيف لمسة من الأناقة والروعة إلى أي مكان.</p>\\n<p>الارتفاع حوالي 75 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\",\"ar\":\"<p>أضف لمسة من الجمال الطبيعي إلى منزلك مع هذا التشكيل الرائع من الزهور المتنوعة. يتضمن الباقة قطعاً من قطعتان من الهايدرينجا الأبيض الجميل، و5 بيبي روز الوردي الفاتح، و10 روز البنفسجي الفاتح، و10 روز أبيض، مع مزيج من الماثيولا البنفسجي الغامق 5 قطع، 3 استوما وردي فاتح، وقطعتان من الستاتس البنفسجي الغامق. إضافة إلى لمسات من اللمينيوم البنفسجي والخضار الطازج، مما يجعل هذه الباقة خياراً مثالياً للزينة أو كهدية رائعة في أي مناسبة. احصل عليها الآن لتضيف لمسة من الأناقة والروعة إلى أي مكان.</p>\\n<p>الارتفاع حوالي 75 سم.</p>\\n<p>العرض حوالي 50 سم.</p>\"}', '705', 'products/1-12.png', '[\"products\\/gallery\\/1-12.png\",\"products\\/gallery\\/2-14.png\",\"products\\/gallery\\/3-13.png\",\"products\\/gallery\\/4-13.png\"]', '{\"en\":\"<p>أضف لمسة من الجمال الطبيعي إلى منزلك مع هذا 