INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('285', '17644', NULL, '[6,7,9,21,32]', NULL, NULL, NULL, '{\"en\":\"G325\",\"ar\":\"G325\"}', 'g325-2', 'g325-2', '{\"en\":\"<p>التقط جمال الطبيعة الخلابة لتعبّر عن مشاعر الحب والإمتنان من خلال باقة في مزهرية رائعة من 15 روز احمر والأبيض مرتبة مع الليليوم والإيستوما البيضاء، بالإضافة إلى زهور 2 هايبركم و1 هيدرينجيا الحمراء مع البيبي أوركيد والكريزنتيموم البيضاء. أجمل المشاعر والأحاسيس تُرسل من خلال عبق 4 بيبي روز احمر والكيراميت الأخضر مع خضارات الإستيل وخضارات البامبو الملتوية لمزيد من الجمال، حيث قام بائعو الزهور الماهرون لدينا بترتيب هذه الباقة بشكل فني لجعلها هدية مميزة.<br />\\nالارتفاع حوالي 30 سم إلى 40 سم.<br />\\nالعرض حوالي 25 سم إلى 35 سم.</p>\",\"ar\":\"<p>التقط جمال الطبيعة الخلابة لتعبّر عن مشاعر الحب والإمتنان من خلال باقة في مزهرية رائعة من 15 روز احمر والأبيض مرتبة مع الليليوم والإيستوما البيضاء، بالإضافة إلى زهور 2 هايبركم و1 هيدرينجيا الحمراء مع البيبي أوركيد والكريزنتيموم البيضاء. أجمل المشاعر والأحاسيس تُرسل من خلال عبق 4 بيبي روز احمر والكيراميت الأخضر مع خضارات الإستيل وخضارات البامبو الملتوية لمزيد من الجمال، حيث قام بائعو الزهور الماهرون لدينا بترتيب هذه الباقة بشكل فني لجعلها هدية مميزة.<br />\\nالارتفاع حوالي 30 سم إلى 40 سم.<br />\\nالعرض حوالي 25 سم إلى 35 سم.</p>\"}', '433', 'products/g32520send20flower20to20jeddah201-600x600-1.jpg', '[\"products\\/gallery\\/g32520send20flower20to20jeddah201-600x600-1.jpg\",\"products\\/gallery\\/g32520send20flower20to20jeddah202-600x600-1.jpg\",\"products\\/gallery\\/g32520send20flower20to20jeddah2