INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('295', '17666', NULL, '[6,7,9,21,32,46]', NULL, NULL, NULL, '{\"en\":\"G317\",\"ar\":\"G317\"}', 'g317-2', 'g317-2', '{\"en\":\"<p>باقة أنيقة من التوليب الأحمر تضم 20 زهرة رائعة، مصحوبة بتنسيق خضري مميز من اللبيديوم والخضار، مما يضيف لمسة من الجمال الطبيعي والانتعاش إلى أي مساحة. هذه الباقة تجمع بين الألوان الجذابة والنكهة الخضراء الطبيعية لتناسب كافة الأذواق وتلائم جميع المناسبات.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>باقة أنيقة من التوليب الأحمر تضم 20 زهرة رائعة، مصحوبة بتنسيق خضري مميز من اللبيديوم والخضار، مما يضيف لمسة من الجمال الطبيعي والانتعاش إلى أي مساحة. هذه الباقة تجمع بين الألوان الجذابة والنكهة الخضراء الطبيعية لتناسب كافة الأذواق وتلائم جميع المناسبات.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '415', 'products/1-21.png', '[\"products\\/gallery\\/1-21.png\",\"products\\/gallery\\/2-23.png\",\"products\\/gallery\\/3-22.png\"]', '{\"en\":\"<p>باقة أنيقة من التوليب الأحمر تضم 20 زهرة رائعة، مصحوبة بتنسيق خضري مميز من اللبيديوم والخضار، مما يضيف لمسة من الجمال الطبيعي والانتعاش إلى أي مساحة. هذه الباقة تجمع بين الألوان الجذابة والنكهة الخضراء الطبيعية لتناسب كافة الأذواق وتلائم جميع المناسبات.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>باقة أنيقة من التوليب الأحمر تضم 20 زهرة رائعة، مصحوبة بتنسيق خضري مميز من اللبيديوم والخضار، مما يضيف لمسة من الجمال الطبيعي والانتعاش إلى أي مساحة. هذه الباقة تجمع بين الألوان الجذابة والنكهة الخضراء الطبيعية لتناسب كافة الأذواق وتلائم جميع المناسبات.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":198,\"name\":\"\\u0623\\u062d\\u0645\\u0631\",\"slug\":\"%d8%a3%d8%ad%d9%85%d8%b1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":210,\"name\":\"\\u062d\\u0628\",\"slug\":\"%d8%ad%d8%a8\"},{\"id\":237,\"name\":\"\\u0641\\u0644\\u0646\\u062a\\u0627\\u064a\\u0646\",\"slug\":\"%d9%81%d9%84%d9%86%d8%aa%d8%a7%d9%8a%d9%86\"},{\"id\":196,\"name\":\"\\u0644\\u0644\\u0631\\u062c\\u0644\",\"slug\":\"%d9%84%d9%84%d8%b1%d8%ac%d9%84\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"}],\"tags\":[],\"wp_ar_id\":17666}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:20:49', '2026-10-07 12:34:14', NULL);
