INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('321', '17726', NULL, '[7,13,16,22,25,32]', NULL, NULL, NULL, '{\"en\":\"G275\",\"ar\":\"G275\"}', 'g275-2', 'g275-2', '{\"en\":\"<p>عبّر عن حبك بعبق الزهور المُنعشة للروح. باقة في مزهرية فاخرة من الهيدرينجيا باللون الأزرق الفاتح مع الروز الابيض والسوليداجو، بالإضافة إلى الكيرميت الأخضر وخضارات اليوكاليبتوس لمزيد من الجمال.</p>\\n<p>اطلق العنان لمشاعرك الدافئة من خلال زهور الإستوما والكالا والكريزنتيموم البيضاء الرائع.</p>\\n<p>الارتفاع حوالي 70 سم إلى 80 سم. العرض حوالي 40 سم إلى 50 سم.</p>\",\"ar\":\"<p>عبّر عن حبك بعبق الزهور المُنعشة للروح. باقة في مزهرية فاخرة من الهيدرينجيا باللون الأزرق الفاتح مع الروز الابيض والسوليداجو، بالإضافة إلى الكيرميت الأخضر وخضارات اليوكاليبتوس لمزيد من الجمال.</p>\\n<p>اطلق العنان لمشاعرك الدافئة من خلال زهور الإستوما والكالا والكريزنتيموم البيضاء الرائع.</p>\\n<p>الارتفاع حوالي 70 سم إلى 80 سم. العرض حوالي 40 سم إلى 50 سم.</p>\"}', '358', 'products/artboard-4-1.jpg', '[\"products\\/gallery\\/artboard-4-1.jpg\",\"products\\/gallery\\/artboard-2-1.jpg\"]', '{\"en\":\"<p>عبّر عن حبك بعبق الزهور المُنعشة للروح. باقة في مزهرية فاخرة من الهيدرينجيا باللون الأزرق الفاتح مع الروز الابيض والسوليداجو، بالإضافة إلى الكيرميت الأخضر وخضارات اليوكاليبتوس لمزيد من الجمال.</p>\\n<p>اطلق العنان لمشاعرك الدافئة من خلال زهور الإستوما والكالا والكريزنتيموم البيضاء الرائع.</p>\\n<p>الارتفاع حوالي 70 سم إلى 80 سم. العرض حوالي 40 سم إلى 50 سم.</p>\",\"ar\":\"<p>عبّر عن حبك بعبق الزهور المُنعشة للروح. باقة في مزهرية فاخرة من الهيدرينجيا باللون الأزرق