INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('322', '17728', NULL, '[3,6,7,13,18,19,20,22,27,32,44,48,49]', NULL, NULL, NULL, '{\"en\":\"G274\",\"ar\":\"G274\"}', 'g274-2', 'g274-2', '{\"en\":\"<p>الألوان الزاهية تجلب الرغبة بالدفء وتنعش الحواس في نفس الوقت. باقة في سلة أنيقة تحتوي على زهور طبيعية من الهيدرينجيا والسمبيديوم باللون الأبيض مع الفيرونيكا والليليوم الأبيض والواكس فلاور. ادخل الفرح والسعادة إلى حياة من تحب من خلال زهور الكريزنتيموم والتوليب والروز باللون الأبيض مع البيبي أوركيد الأبيض وخضارات البامبو الملتوية.</p>\\n<p>الارتفاع حوالي 45 سم إلى 55 سم.</p>\\n<p>العرض حوالي 35 سم إلى 45 سم.</p>\",\"ar\":\"<p>الألوان الزاهية تجلب الرغبة بالدفء وتنعش الحواس في نفس الوقت. باقة في سلة أنيقة تحتوي على زهور طبيعية من الهيدرينجيا والسمبيديوم باللون الأبيض مع الفيرونيكا والليليوم الأبيض والواكس فلاور. ادخل الفرح والسعادة إلى حياة من تحب من خلال زهور الكريزنتيموم والتوليب والروز باللون الأبيض مع البيبي أوركيد الأبيض وخضارات البامبو الملتوية.</p>\\n<p>الارتفاع حوالي 45 سم إلى 55 سم.</p>\\n<p>العرض حوالي 35 سم إلى 45 سم.</p>\"}', '357', 'products/g27420jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/g27420jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/g27420send20flower20to20jeddah20-600x600-1.jpg\",\"products\\/gallery\\/g27420send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g274-jeddah-flower-delivery-600x600-1.jpg\"]', '{\"en\":\"<p>الألوان الزاهية تجلب الرغبة بالدفء وتنعش الحواس في نفس الوقت. باقة في سلة أنيقة تحتوي على زهور طبيعية من الهيدرينجيا والسمبيديوم باللون الأبيض مع الفيرونيكا والليليوم الأبيض والواكس فلاور. ادخل الفرح والسعادة إلى حياة من تحب من خلال زهور الكريزنتيموم والتوليب والروز باللون الأبيض مع البيبي أوركيد الأبيض وخضارات البامبو الملتوية.</p>\\n<p>الارتفاع حوالي 45 سم إلى 55 سم.</p>\\n<p>العرض حوالي 35 سم إلى 45 سم.</p>\",\"ar\":\"<p>الألوان الزاهية تجلب الرغبة بالدفء وتنعش الحواس في نفس الوقت. باقة في سلة أنيقة تحتوي على زهور طبيعية من الهيدرينجيا والسمبيديوم باللون الأبيض مع الفيرونيكا والليليوم الأبيض والواكس فلاور. ادخل الفرح والسعادة إلى حياة من تحب من خلال زهور الكريزنتيموم والتوليب والروز باللون الأبيض مع البيبي أوركيد الأبيض وخضارات البامبو الملتوية.</p>\\n<p>الارتفاع حوالي 45 سم إلى 55 سم.</p>\\n<p>العرض حوالي 35 سم إلى 45 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":202,\"name\":\"\\u0623\\u0628\\u064a\\u0636\",\"slug\":\"%d8%a3%d8%a8%d9%8a%d8%b6\"},{\"id\":239,\"name\":\"\\u0627\\u0644\\u0639\\u064a\\u062f\",\"slug\":\"%d8%a7%d9%84%d8%b9%d9%8a%d8%af\"},{\"id\":235,\"name\":\"\\u0627\\u0644\\u064a\\u0648\\u0645 \\u0627\\u0644\\u0648\\u0637\\u0646\\u064a\",\"slug\":\"%d8%a7%d9%84%d9%8a%d9%88%d9%85-%d8%a7%d9%84%d9%88%d8%b7%d9%86%d9%8a\"},{\"id\":216,\"name\":\"\\u062a\\u062e\\u0631\\u062c\",\"slug\":\"%d8%aa%d8%ae%d8%b1%d8%ac\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":207,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0627\\u062a\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d9%85%d9%86%d8%a7%d8%b3%d8%a8%d8%a7%d8%aa\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug