INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('334', '17758', NULL, '[6,14,20,22,23,24,27,29,32]', NULL, NULL, NULL, '{\"en\":\"G255\",\"ar\":\"G255\"}', 'g255-2', 'g255-2', '{\"en\":\"<p>استمتع بأجمل اللحظات مع أحبتك وقم بإهداء باقة في مزهرية ملفتة للنظر تتكون من السمبيديوم البنفسجي والهيدرينجيا البيضاء مع الليليوم باللون الأبيض والوردي الجميل، بالإضافة إلى الروز الوردي والكالا باللون البنفسجي لترسل أجمل المشاعر وتتقرب أكثر من أحبتك. هدية رائعة مكونة من زهور جذابة كالإيستوما البيضاء والواكس فلاور باللون البنفسجي والأبيض، بالإضافة إلى خضارات طبيعية لتضيف مظهرًا فريدًا مستوحاة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 60 سم إلى 70 سم.</p>\\n<p>العرض حوالي 30 سم إلى 40 سم.</p>\",\"ar\":\"<p>استمتع بأجمل اللحظات مع أحبتك وقم بإهداء باقة في مزهرية ملفتة للنظر تتكون من السمبيديوم البنفسجي والهيدرينجيا البيضاء مع الليليوم باللون الأبيض والوردي الجميل، بالإضافة إلى الروز الوردي والكالا باللون البنفسجي لترسل أجمل المشاعر وتتقرب أكثر من أحبتك. هدية رائعة مكونة من زهور جذابة كالإيستوما البيضاء والواكس فلاور باللون البنفسجي والأبيض، بالإضافة إلى خضارات طبيعية لتضيف مظهرًا فريدًا مستوحاة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 60 سم إلى 70 سم.</p>\\n<p>العرض حوالي 30 سم إلى 40 سم.</p>\"}', '326', 'products/g25520jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/g25520jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/g25520send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g255-jeddah-flower-delivery-600x600-1.jpg\"]', '{\"en\":\"<p>استمتع بأجمل اللحظات مع أحبتك وقم بإهداء باقة في مزهرية ملفتة للنظر تتكون من السمبيديوم البنفسجي والهيدرينجيا البيضاء مع الليليوم باللون الأبيض والوردي الجميل، بالإضافة إلى الروز الوردي والكالا باللون البنفسجي لترسل أجمل المشاعر وتتقرب أكثر من أحبتك. هدية رائعة مكونة من زهور جذابة كالإيستوما البيضاء والواكس فلاور باللون البنفسجي والأبيض، بالإضافة إلى خضارات طبيعية لتضيف مظهرًا فريدًا مستوحاة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 60 سم إلى 70 سم.</p>\\n<p>العرض حوالي 30 سم إلى 40 سم.</p>\",\"ar\":\"<p>استمتع بأجمل اللحظات مع أحبتك وقم بإهداء باقة في مزهرية ملفتة للنظر تتكون من السمبيديوم البنفسجي والهيدرينجيا البيضاء مع الليليوم باللون الأبيض والوردي الجميل، بالإضافة إلى الروز الوردي والكالا باللون البنفسجي لترسل أجمل المشاعر وتتقرب أكثر من أحبتك. هدية رائعة مكونة من زهور جذابة كالإيستوما البيضاء والواكس فلاور باللون البنفسجي والأبيض، بالإضافة إلى خضارات طبيعية لتضيف مظهرًا فريدًا مستوحاة من جمال الطبيعة الخلابة.</p>\\n<p>الارتفاع حوالي 60 سم إلى 70 سم.</p>\\n<p>العرض حوالي 30 سم إلى 40 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":216,\"name\":\"\\u062a\\u062e\\u0631\\u062c\",\"slug\":\"%d8%aa%d8%ae%d8%b1%d8%ac\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug\":\"%d8%b9%d9%8a%d8%af-%d9%85%d9%8a%d9%84%d8%a7%d8%af\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"},{\"id\":212,\"name\":\"\\u0645\\u0648\\u0644\\u0648\\u062f \\u062c\\u062f\\u064a\\u062f\",\"slug\":\"%d9%85%d9%88%d9%84%d9%88%d8%af-%d8%ac%d8%af%d9