INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('352', '17794', NULL, '[4,6,7,13,16,22,23,24,32,44,48,49]', NULL, NULL, NULL, '{\"en\":\"G205\",\"ar\":\"G205\"}', 'g205-2', 'g205-2', '{\"en\":\"<p>استمتع بأجواء من الرقي والجمال مع باقة الزهور البيضاء الفاخرة التي تجمع بين التوليب الأبيض، الهايدرنجا، الليليوم، الاستوما، والبيبي أوركيد. تأتي هذه الباقة المميزة التي تضم 2 قطع من الهايدرنجا الأبيض، 10 قطع من التوليب الأبيض، 3 قطع من الاستوما الأبيض، 2 قطع من الليليوم الأبيض، و5 قطع من البيبي أوركيد، مع لمسة من الخضار الطازج لإضفاء مزيد من الأناقة والانتعاش. هذه الباقة المتكاملة والمثالية هي الخيار الأمثل لإهداء أحبائك في المناسبات الخاصة أو تزيين منزلك بأجواء هادئة وفخمة.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\",\"ar\":\"<p>استمتع بأجواء من الرقي والجمال مع باقة الزهور البيضاء الفاخرة التي تجمع بين التوليب الأبيض، الهايدرنجا، الليليوم، الاستوما، والبيبي أوركيد. تأتي هذه الباقة المميزة التي تضم 2 قطع من الهايدرنجا الأبيض، 10 قطع من التوليب الأبيض، 3 قطع من الاستوما الأبيض، 2 قطع من الليليوم الأبيض، و5 قطع من البيبي أوركيد، مع لمسة من الخضار الطازج لإضفاء مزيد من الأناقة والانتعاش. هذه الباقة المتكاملة والمثالية هي الخيار الأمثل لإهداء أحبائك في المناسبات الخاصة أو تزيين منزلك بأجواء هادئة وفخمة.</p>\\n<p>الارتفاع حوالي 50 سم.</p>\\n<p>العرض حوالي 40 سم.</p>\"}', '277', 'products/1-39.png', '[\"products\\/gallery\\/1-39.png\",\"products\\/gallery\\/2-42.png\",\"products\\/gallery\\/3-40.png\",\"products\\/gallery\\/4-37.png\",\"products\\/gallery\\/5-19.png\"]', '{\"en\":\"<p>استمتع بأجواء م