INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('353', '17802', NULL, '[6,19,22,27,29,32,48,53]', NULL, NULL, NULL, '{\"en\":\"G199\",\"ar\":\"G199\"}', 'g199-2', 'g199-2', '{\"en\":\"<p>باقة يد نابضة بالحياة، تتكون من 35 وردة بنفسجية ووردية فاتحة، وزهور الواكس الأبيض الرقيقة ، الليمونيوم البنفسجي. كما تضم ​​هذه الباقة الجميلة زهور الهيدرنجا والجوري الأبيض ، وزهرة الاستوما البنفسجية الداكنة، لإضفاء ابتسامة ساحرة على وجه من تحب.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\",\"ar\":\"<p>باقة يد نابضة بالحياة، تتكون من 35 وردة بنفسجية ووردية فاتحة، وزهور الواكس الأبيض الرقيقة ، الليمونيوم البنفسجي. كما تضم ​​هذه الباقة الجميلة زهور الهيدرنجا والجوري الأبيض ، وزهرة الاستوما البنفسجية الداكنة، لإضفاء ابتسامة ساحرة على وجه من تحب.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\"}', '271', 'products/101-37.png', '[\"products\\/gallery\\/101-37.png\",\"products\\/gallery\\/102-36.png\",\"products\\/gallery\\/103-37.png\",\"products\\/gallery\\/104-31.png\",\"products\\/gallery\\/105-23.png\"]', '{\"en\":\"<p>باقة يد نابضة بالحياة، تتكون من 35 وردة بنفسجية ووردية فاتحة، وزهور الواكس الأبيض الرقيقة ، الليمونيوم البنفسجي. كما تضم ​​هذه الباقة الجميلة زهور الهيدرنجا والجوري الأبيض ، وزهرة الاستوما البنفسجية الداكنة، لإضفاء ابتسامة ساحرة على وجه من تحب.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\",\"ar\":\"<p>باقة يد نابضة بالحياة، تتكون من 35 وردة بنفسجية ووردية فاتحة، وزهور الواكس الأبيض الرقيقة ، الليمونيوم البنفسجي. كما تضم ​​هذه الباقة الجميلة زهور الهيدرنجا والجوري الأبيض ، وزهرة الاستوما البنفسجية الداكنة، لإضفاء ابتسامة ساحرة على وجه من تحب.</p>\\n<p>الارتفاع حوالي 65 سم.</p>\\n<p>العرض حوالي 55 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":264,\"name\":\".\",\"slug\":\"264\"},{\"id\":239,\"name\":\"\\u0627\\u0644\\u0639\\u064a\\u062f\",\"slug\":\"%d8%a7%d9%84%d8%b9%d9%8a%d8%af\"},{\"id\":216,\"name\":\"\\u062a\\u062e\\u0631\\u062c\",\"slug\":\"%d8%aa%d8%ae%d8%b1%d8%ac\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":208,\"name\":\"\\u0644\\u0644\\u0623\\u0645\",\"slug\":\"%d9%84%d9%84%d8%a3%d9%85\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"},{\"id\":218,\"name\":\"\\u0647\\u0627\\u0646\\u062f \\u0628\\u0648\\u0643\\u064a\\u0647\",\"slug\":\"%d9%87%d8%a7%d9%86%d8%af-%d8%a8%d9%88%d9%83%d9%8a%d9%87\"}],\"tags\":[],\"wp_ar_id\":17802}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '450.00', '450.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:21:05', '2026-10-07 12:39:25', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('354', '17804', NULL, '[3,5,6,14,19,20,22,23,24,32,48]', NULL, NULL, NULL, '{\"en\":\"G196\",\"ar\":\"G196\"}', 'g196-2', 'g196-2', '{\"en\":\"<p>تنسيق فاخر يجمع بين الأناقة والرقي، يتألق بتدرجات الوردي والبنفسجي في مزيج متناغم من هايدرينجا وردي فاتح، واليليوم الوردي، تتخللها لمسات ناعمة من بيبي أوركيد أبيض، وآلستروميريا أبيض، وكريزنتيموم أبيض، مع كيرميت وخضار منسق بعناية تضيف لمسة طبيعية أنيقة. تصميم يعبر عن الذوق الرفيع والمشاعر الصادقة، ويليق بكل مناسبة بأسلوب راقٍ ومميز.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>تنسيق فاخر يجمع بين الأناقة والرقي، يتألق بتدرجات الوردي والبنفسجي في مزيج متناغم من هايدرينجا وردي فاتح، واليليوم الوردي، تتخللها لمسات ناعمة من بيبي أوركيد أبيض، وآلستروميريا أبيض، وكريزنتيموم أبيض، مع كيرميت وخضار منسق بعناية تضيف لمسة طبيعية أنيقة. تصميم يعبر عن الذوق الرفيع والمشاعر الصادقة، ويليق بكل مناسبة بأسلوب راقٍ ومميز.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '268', 'products/1-26.png', '[\"products\\/gallery\\/1-26.png\",\"products\\/gallery\\/2-28.png\",\"products\\/gallery\\/3-27.png\",\"products\\/gallery\\/4-25.png\"]', '{\"en\":\"<p>تنسيق فاخر يجمع بين الأناقة والرقي، يتألق بتدرجات الوردي والبنفسجي في مزيج متناغم من هايدرينجا وردي فاتح، واليليوم الوردي، تتخللها لمسات ناعمة من بيبي أوركيد أبيض، وآلستروميريا أبيض، وكريزنتيموم أبيض، مع كيرميت وخضار منسق بعناية تضيف لمسة طبيعية أنيقة. تصميم يعبر عن الذوق الرفيع والمشاعر الصادقة، ويليق بكل مناسبة بأسلوب راقٍ ومميز.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>تنسيق فاخر يجمع بين الأناقة والرقي، يتألق بتدرجات الوردي والبنفسجي في مزيج متناغم من هايدرينجا وردي فاتح، واليليوم الوردي، تتخللها لمسات ناعمة من بيبي أوركيد أبيض، وآلستروميريا أبيض، وكريزنتيموم أبيض، مع كيرميت وخضار منسق بعناية تضيف لمسة طبيعية أنيقة. تصميم يعبر عن الذوق الرفيع والمشاعر الصادقة، ويليق بكل مناسبة بأسلوب راقٍ ومميز.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":141,\"name\":\"Best Seller\",\"slug\":\"best-seller\"},{\"id\":194,\"name\":\"\\u0627\\u0644\\u0623\\u0641\\u0636\\u0644 \\u0645\\u0628\\u064a\\u0639\\u0627\\u064b\",\"slug\":\"%d8%a7%d9%84%d8%a3%d9%81%d8%b6%d9%84-%d9%85%d8%a8%d9%8a%d8%b9%d8%a7%d9%8b\"},{\"id\":239,\"name\":\"\\u0627\\u0644\\u0639\\u064a\\u062f\",\"slug\":\"%d8%a7%d9%84%d8%b9%d9%8a%d8%af\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug\":\"%d8%b9%d9%8a%d8%af-%d9%85%d9%8a%d9%84%d8%a7%d8%af\"},{\"id\":208,\"name\":\"\\u0644\\u0644\\u0623\\u0645\",\"slug\":\"%d9%84%d9%84%d8%a3%d9%85\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"},{\"id\":212,\"name\":\"\\u0645\\u0648\\u0644\\u0648\\u062f \\u062c\\u062f\\u064a\\u062f\",\"slug\":\"%d9%85%d9%88%d9%84%d9%88%d8%af-%d8%ac%d8%af%d9%8a%d8%af\"},{\"id\":192,\"name\":\"\\u0645\\u0648\\u0644\\u0648\\u062f\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629\",\"slug\":\"%d9%85%d9%88%d9%84%d9%88%d8%af%d8%a9-%d8%ac%d8%af%d9%8a%d8%af%d8%a9\"},{\"id\":203,\"name\":\"\\u0648\\u0631\\u062f\\u064a\",\"slug\":\"%d9%88%d8%b1%d8%af%d9%8a\"},{\"id\":213,\"name\":\"\\u0648\\u0638\\u064a\\u0641\\u0629 \\u0648\\u062a\\u0631\\u0642\\u064a\\u0629\",\"slug\":\"%d9%88%d8%b8%d9%8a%d9%81%d8%a9-%d9%88%d8%aa%d8%b1%d9%82%d9%8a%d8%a9\"}],\"tags\":[],\"wp_ar_id\":17804}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '250.00', '250.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:21:06', '2026-10-07 12:39:31', NULL);
