INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('363', '17822', NULL, '[3,4,6,7,14,20,21,22,27,29,32,46,49]', NULL, NULL, NULL, '{\"en\":\"G162\",\"ar\":\"G162\"}', 'g162', 'g162', '{\"en\":\"<p>دع هديتك المميزة تترك عنك انطباعًا جميلًا عند أحبائك. ابتكرو خبرائنا احدث التنسيقات الجذابة التي تجميع أناقتها من الزهور الراقية .مصممة بشكل فني لتكن أنت السبب وراء سعادتهم.<br />\\nمكونه من الجوري الأحمر  والبيبي جوري الأبيض مع زهور الجبسوفيليا و لمسات رقيقة من خضارات السولي داغو هدية ملائمة لجميع المناسابات.<br />\\nالارتفاع 60سم.<br />\\nالعرض 45 سم.</p>\",\"ar\":\"<p>دع هديتك المميزة تترك عنك انطباعًا جميلًا عند أحبائك. ابتكرو خبرائنا احدث التنسيقات الجذابة التي تجميع أناقتها من الزهور الراقية .مصممة بشكل فني لتكن أنت السبب وراء سعادتهم.<br />\\nمكونه من الجوري الأحمر  والبيبي جوري الأبيض مع زهور الجبسوفيليا و لمسات رقيقة من خضارات السولي داغو هدية ملائمة لجميع المناسابات.<br />\\nالارتفاع 60سم.<br />\\nالعرض 45 سم.</p>\"}', '234', 'products/107-1.png', '[\"products\\/gallery\\/107-1.png\",\"products\\/gallery\\/104png.png\",\"products\\/gallery\\/105-7.png\",\"products\\/gallery\\/101-8.png\",\"products\\/gallery\\/102png.png\"]', '{\"en\":\"<p>دع هديتك المميزة تترك عنك انطباعًا جميلًا عند أحبائك. ابتكرو خبرائنا احدث التنسيقات الجذابة التي تجميع أناقتها من الزهور الراقية .مصممة بشكل فني لتكن أنت السبب وراء سعادتهم.<br />\\nمكونه من الجوري الأحمر  والبيبي جوري الأبيض مع زهور الجبسوفيليا و لمسات رقيقة من خضارات السولي داغو هدية ملائمة لجميع المناسابات.<br />\\nالارتفاع 60سم.<br />\\nالعرض 45 سم.</p>\",\"ar\":\"<p>د