INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('368', '17834', NULL, '[3,4,6,7,10,13,16,20,22,27,32,48]', NULL, NULL, NULL, '{\"en\":\"G155\",\"ar\":\"G155\"}', 'g155-2', 'g155-2', '{\"en\":\"<p>امنح أحب الناس إلى قلبك هذه الباقة الرائعة. تحفة مستوحاة من الطبيعة الخلابة تناسب كل المواسم مكونة من مجموعة عصرية وأنيقة من الأزهار الجميلة. هدية مُبهجة من البيبي روز الأصفر النابض بالحياة والهيدرينجيا الخضراء مع البيبي أوركيد الأبيض والسوليداجو، كما أضفنا الهايبركم الأخضر والروز والكريزنتيموم الأبيض لتُنعش حواس أحبتك وترسل مشاعرك الصادقة عبر عبق الزهور.<br />\\nيبلغ الارتفاع حوالي 50 سم إلى 60 سم.<br />\\nالعرض حوالي 25 سم إلى 30 سم.</p>\",\"ar\":\"<p>امنح أحب الناس إلى قلبك هذه الباقة الرائعة. تحفة مستوحاة من الطبيعة الخلابة تناسب كل المواسم مكونة من مجموعة عصرية وأنيقة من الأزهار الجميلة. هدية مُبهجة من البيبي روز الأصفر النابض بالحياة والهيدرينجيا الخضراء مع البيبي أوركيد الأبيض والسوليداجو، كما أضفنا الهايبركم الأخضر والروز والكريزنتيموم الأبيض لتُنعش حواس أحبتك وترسل مشاعرك الصادقة عبر عبق الزهور.<br />\\nيبلغ الارتفاع حوالي 50 سم إلى 60 سم.<br />\\nالعرض حوالي 25 سم إلى 30 سم.</p>\"}', '227', 'products/g15520jeddah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/g15520jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/g15520send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/g155-send-flowers-to-jeddah-600x600-1.jpg\"]', '{\"en\":\"<p>امنح أحب الناس إلى قلبك هذه الباقة الرائعة. تحفة مستوحاة من الطبيعة الخلابة تناسب كل المواسم مكونة من مجموعة عصرية وأنيقة من الأزهار الجميلة. هدية مُبهجة من البيبي روز الأصفر النابض بالحياة والهيدرينجيا الخضراء مع البيبي أوركيد الأبيض والسوليداجو، كما أضفنا الهايبركم الأخضر والروز والكريزنتيموم الأبيض لتُنعش حواس أحبتك وترسل مشاعرك الصادقة عبر عبق الزهور.<br />\\nيبلغ الارتفاع حوالي 50 سم إلى 60 سم.<br />\\nالعرض حوالي 25 سم إلى 30 سم.</p>\",\"ar\":\"<p>امنح أحب الناس إلى قلبك هذه الباقة الرائعة. تحفة مستوحاة من الطبيعة الخلابة تناسب كل المواسم مكونة من مجموعة عصرية وأنيقة من الأزهار الجميلة. هدية مُبهجة من البيبي روز الأصفر النابض بالحياة والهيدرينجيا الخضراء مع البيبي أوركيد الأبيض والسوليداجو، كما أضفنا الهايبركم الأخضر والروز والكريزنتيموم الأبيض لتُنعش حواس أحبتك وترسل مشاعرك الصادقة عبر عبق الزهور.<br />\\nيبلغ الارتفاع حوالي 50 سم إلى 60 سم.<br />\\nالعرض حوالي 25 سم إلى 30 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":202,\"name\":\"\\u0623\\u0628\\u064a\\u0636\",\"slug\":\"%d8%a3%d8%a8%d9%8a%d8%b6\"},{\"id\":205,\"name\":\"\\u0623\\u062e\\u0636\\u0631\",\"slug\":\"%d8%a3%d8%ae%d8%b6%d8%b1\"},{\"id\":199,\"name\":\"\\u0623\\u0635\\u0641\\u0631\",\"slug\":\"%d8%a3%d8%b5%d9%81%d8%b1\"},{\"id\":193,\"name\":\"\\u0627\\u0639\\u062a\\u0630\\u0627\\u0631\",\"slug\":\"%d8%a7%d8%b9%d8%aa%d8%b0%d8%a7%d8%b1\"},{\"id\":239,\"name\":\"\\u0627\\u0644\\u0639\\u064a\\u062f\",\"slug\":\"%d8%a7%d9%84%d8%b9%d9%8a%d8%af\"},{\"id\":216,\"name\":\"\\u062a\\u062e\\u0631\\u062c\",\"slug\":\"%d8%aa%d8%ae%d8%b1%d8%ac\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug\":\"%d8%b9%d9%8a%d8%af-%d9%85%d9%8a%d9%84%d8%a7%d8%