INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('381', '17866', NULL, '[3,4,6,7,14,19,20,22,23,24,32]', NULL, NULL, NULL, '{\"en\":\"G113\",\"ar\":\"G113\"}', 'g113-2', 'g113-2', '{\"en\":\"<p>باقة مميزة تجمع بين أجمل الألوان والأنواع من الزهور الفاخرة، حيث تحتوي على 22 وردة روز وردي غامق، ليليوم وردي، أوركيد بيبي وردي، كريزنتيموم بنفسجي فاتح، إضافة إلى لمسات من لمينيوم بنفسجي وخضار طبيعي يضفي رونقاً طبيعياً على التصميم. تعد هذه الباقة خياراً رائعاً لأي مناسبة، حيث تتناغم الألوان الزاهية والتصميم المتقن لتخلق لمسة من الجمال والانتعاش، لتناسب ذوق الجميع من مختلف الأعمار.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\",\"ar\":\"<p>باقة مميزة تجمع بين أجمل الألوان والأنواع من الزهور الفاخرة، حيث تحتوي على 22 وردة روز وردي غامق، ليليوم وردي، أوركيد بيبي وردي، كريزنتيموم بنفسجي فاتح، إضافة إلى لمسات من لمينيوم بنفسجي وخضار طبيعي يضفي رونقاً طبيعياً على التصميم. تعد هذه الباقة خياراً رائعاً لأي مناسبة، حيث تتناغم الألوان الزاهية والتصميم المتقن لتخلق لمسة من الجمال والانتعاش، لتناسب ذوق الجميع من مختلف الأعمار.</p>\\n<p>الارتفاع حوالي 55 سم.</p>\\n<p>العرض حوالي 45 سم.</p>\"}', '185', 'products/101-75.png', '[\"products\\/gallery\\/101-75.png\",\"products\\/gallery\\/104-63.png\",\"products\\/gallery\\/103-68.png\",\"products\\/gallery\\/102-69.png\"]', '{\"en\":\"<p>باقة مميزة تجمع بين أجمل الألوان والأنواع من الزهور الفاخرة، حيث تحتوي على 22 وردة روز وردي غامق، ليليوم وردي، أوركيد بيبي وردي، كريزنتيموم بنفسجي فاتح، إضافة إلى لمسات من لمينيوم بنفسجي وخضار طبيعي يضفي رونقاً طبيعياً على التصميم. تعد