INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('391', '17890', NULL, '[6,14,18,19,20,22,23,24,27,32]', NULL, NULL, NULL, '{\"en\":\"G093\",\"ar\":\"G093\"}', 'g093-2', 'g093-2', '{\"en\":\"<p>تشكيلة جديدة بتصميم عصري من تنسيق خبرائنا، تُقدَّم كباقة فاخرة تليق بمن استثنى مكانته في قلبك.</p>\\n<p>دع هديتك المميزة تترك عنك انطباعًا جميلًا عند أحبائك. التي تجمع بين أجود أنواع الزهور الفاخرة.<br />\\nمكونه من الجيربيرا والاستوما الأبيض و الهيدرينجا الوردي , واغضان السمبيديوم الأبيض مع لمسات رقيقة من خضارات الإستيل وعشب الموس اختيار راقٍ لكل لحظة مميزة.<br />\\nالارتفاع حوالي 55 سم إلى 60 سم.<br />\\nالعرض حوالي 40 سم إلى 45 سم.</p>\",\"ar\":\"<p>تشكيلة جديدة بتصميم عصري من تنسيق خبرائنا، تُقدَّم كباقة فاخرة تليق بمن استثنى مكانته في قلبك.</p>\\n<p>دع هديتك المميزة تترك عنك انطباعًا جميلًا عند أحبائك. التي تجمع بين أجود أنواع الزهور الفاخرة.<br />\\nمكونه من الجيربيرا والاستوما الأبيض و الهيدرينجا الوردي , واغضان السمبيديوم الأبيض مع لمسات رقيقة من خضارات الإستيل وعشب الموس اختيار راقٍ لكل لحظة مميزة.<br />\\nالارتفاع حوالي 55 سم إلى 60 سم.<br />\\nالعرض حوالي 40 سم إلى 45 سم.</p>\"}', '165', 'products/jpg.jpg', '[\"products\\/gallery\\/jpg.jpg\",\"products\\/gallery\\/g.jpg\",\"products\\/gallery\\/101-21.jpg\",\"products\\/gallery\\/unnamed-file.jpg\"]', '{\"en\":\"<p>تشكيلة جديدة بتصميم عصري من تنسيق خبرائنا، تُقدَّم كباقة فاخرة تليق بمن استثنى مكانته في قلبك.</p>\\n<p>دع هديتك المميزة تترك عنك انطباعًا جميلًا عند أحبائك. التي تجمع بين أجود أنواع الزهور الفاخرة.<br />\\nمكونه من الجيربيرا والاستوما الأبيض و اله