INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('393', '17894', NULL, '[4,6,7,13,16,18,20,22,23,24,32,44,48]', NULL, NULL, NULL, '{\"en\":\"G088\",\"ar\":\"G088\"}', 'g088-2', 'g088-2', '{\"en\":\"<p>باقة فاخرة تجمع بين الجمال الطبيعي والأناقة العصرية، تضم 3 هايدرينجا خضراء، و15 روز بيضاء، 4 ستوما بيضاء، مع خضارات الكيرميت، وسوليداجو، كريزنتيموم أبيض، و3 جبسوفيليا، منسقة بعناية لتمنحك تناغماً مبهراً بين الألوان والملمس. هذه الباقة مثالية كهديّة راقية تعبّر عن النقاء والرقي، أو كقطعة ديكور أنيقة تضفي لمسة من الانتعاش والجمال على أي مكان.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\",\"ar\":\"<p>باقة فاخرة تجمع بين الجمال الطبيعي والأناقة العصرية، تضم 3 هايدرينجا خضراء، و15 روز بيضاء، 4 ستوما بيضاء، مع خضارات الكيرميت، وسوليداجو، كريزنتيموم أبيض، و3 جبسوفيليا، منسقة بعناية لتمنحك تناغماً مبهراً بين الألوان والملمس. هذه الباقة مثالية كهديّة راقية تعبّر عن النقاء والرقي، أو كقطعة ديكور أنيقة تضفي لمسة من الانتعاش والجمال على أي مكان.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\"}', '160', 'products/1-43.png', '[\"products\\/gallery\\/1-43.png\",\"products\\/gallery\\/2-49.png\",\"products\\/gallery\\/3-47.png\",\"products\\/gallery\\/4-45.png\"]', '{\"en\":\"<p>باقة فاخرة تجمع بين الجمال الطبيعي والأناقة العصرية، تضم 3 هايدرينجا خضراء، و15 روز بيضاء، 4 ستوما بيضاء، مع خضارات الكيرميت، وسوليداجو، كريزنتيموم أبيض، و3 جبسوفيليا، منسقة بعناية لتمنحك تناغماً مبهراً بين الألوان والملمس. هذه الباقة مثالية كهديّة راقية تعبّر عن النقاء والرقي، أو كقطعة ديكور أنيقة تضفي لمسة من الانتعاش والجمال على أي مكان.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\",\"ar\":\"<p>باقة فاخرة تجمع بين الجمال الطبيعي والأناقة العصرية، تضم 3 هايدرينجا خضراء، و15 روز بيضاء، 4 ستوما بيضاء، مع خضارات الكيرميت، وسوليداجو، كريزنتيموم أبيض، و3 جبسوفيليا، منسقة بعناية لتمنحك تناغماً مبهراً بين الألوان والملمس. هذه الباقة مثالية كهديّة راقية تعبّر عن النقاء والرقي، أو كقطعة ديكور أنيقة تضفي لمسة من الانتعاش والجمال على أي مكان.</p>\\n<p>الارتفاع حوالي 60 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":202,\"name\":\"\\u0623\\u0628\\u064a\\u0636\",\"slug\":\"%d8%a3%d8%a8%d9%8a%d8%b6\"},{\"id\":205,\"name\":\"\\u0623\\u062e\\u0636\\u0631\",\"slug\":\"%d8%a3%d8%ae%d8%b6%d8%b1\"},{\"id\":193,\"name\":\"\\u0627\\u0639\\u062a\\u0630\\u0627\\u0631\",\"slug\":\"%d8%a7%d8%b9%d8%aa%d8%b0%d8%a7%d8%b1\"},{\"id\":239,\"name\":\"\\u0627\\u0644\\u0639\\u064a\\u062f\",\"slug\":\"%d8%a7%d9%84%d8%b9%d9%8a%d8%af\"},{\"id\":235,\"name\":\"\\u0627\\u0644\\u064a\\u0648\\u0645 \\u0627\\u0644\\u0648\\u0637\\u0646\\u064a\",\"slug\":\"%d8%a7%d9%84%d9%8a%d9%88%d9%85-%d8%a7%d9%84%d9%88%d8%b7%d9%86%d9%8a\"},{\"id\":211,\"name\":\"\\u062a\\u0645\\u0646\\u064a \\u0628\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621\",\"slug\":\"%d8%aa%d9%85%d9%86%d9%8a-%d8%a8%d8%a7%d9%84%d8%b4%d9%81%d8%a7%d8%a1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":207,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0627\\u062a\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d9%85%d9%86%d8%a7%d8%b3%d8%a8%d8%a7%d8%aa\"},{\"id\":209,\"name\":\"\\u0639\\u064a\\u062f \\u0645\\u064a\\u0644\\u0627\\u062f\",\"slug\":\"%d8%b9%d9%8a%d8%af-%d9%85%d9%8a%d9%84%d8%a7%d8%af\"},{\"id\":196,\"name\":\"\\u0644\\u0644