INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('395', '17898', NULL, '[4,6,7,11,14,19,20,22,23,32]', NULL, NULL, NULL, '{\"en\":\"G083\",\"ar\":\"G083\"}', 'g083-2', 'g083-2', '{\"en\":\"<p>استمتع بتجربة جمالية فريدة مع تنسيق الزهور الذي يجمع بين اللمسة الطبيعية والرفاهية المتميزة. يتكون التشكيل من روز أبيض رائع وكريزنتيموم بنفسجي غامق، إضافة إلى الهايدرينجا الأبيض الذي يعكس الهدوء والانتعاش. لمسة من الخضار تعزز من جمال التشكيلة وتضفي عليها رونقًا خاصًا. تصميم عصري وأنيق يناسب مختلف الأذواق ويضفي لمسة من الفخامة في أي مكان. سواء كنت تبحث عن هدية مميزة أو تود تجميل مساحة معينة، هذا التشكيل الزهري هو الخيار المثالي.</p>\\n<p>الارتفاع حوالي 25 سم.</p>\\n<p>العرض حوالي 20 سم.</p>\",\"ar\":\"<p>استمتع بتجربة جمالية فريدة مع تنسيق الزهور الذي يجمع بين اللمسة الطبيعية والرفاهية المتميزة. يتكون التشكيل من روز أبيض رائع وكريزنتيموم بنفسجي غامق، إضافة إلى الهايدرينجا الأبيض الذي يعكس الهدوء والانتعاش. لمسة من الخضار تعزز من جمال التشكيلة وتضفي عليها رونقًا خاصًا. تصميم عصري وأنيق يناسب مختلف الأذواق ويضفي لمسة من الفخامة في أي مكان. سواء كنت تبحث عن هدية مميزة أو تود تجميل مساحة معينة، هذا التشكيل الزهري هو الخيار المثالي.</p>\\n<p>الارتفاع حوالي 25 سم.</p>\\n<p>العرض حوالي 20 سم.</p>\"}', '155', 'products/101-67.png', '[\"products\\/gallery\\/101-67.png\",\"products\\/gallery\\/105-36.png\",\"products\\/gallery\\/102-63.png\",\"products\\/gallery\\/104-57.png\",\"products\\/gallery\\/103-61.png\"]', '{\"en\":\"<p>استمتع بتجربة جمالية فريدة مع تنسيق الزهور الذي يجمع بين اللمسة الطبيعية والرفاهية المتميزة. يتكون التشكي