INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('398', '17906', NULL, '[3,6,14,19,20,22,23,24,32,50]', NULL, NULL, NULL, '{\"en\":\"G070\",\"ar\":\"G070\"}', 'g070-2', 'g070-2', '{\"en\":\"<p>تألّق بتصميم زهري يعكس الأناقة والذوق الرفيع، يجمع بين روعة الطبيعة وسحر التفاصيل. يتكوّن هذا التنسيق من 20 روز وردية غامقة تنبض بالحيوية والرقي، تتوسطها 5 أزهار كريزنتيموم بيضاء تضفي لمسة من النقاء والتوازن، مع لمسات من الخضار الطبيعي التي تعزز جمال الترتيب وتمنحه طابعًا عصريًا أنيقًا. تنسيق مثالي لكل مناسبة، يعبّر عن الفخامة بأسلوب بسيط وجذاب.</p>\\n<p>الارتفاع حوالي 30 سم.</p>\\n<p>العرض حوالي 25 سم.</p>\",\"ar\":\"<p>تألّق بتصميم زهري يعكس الأناقة والذوق الرفيع، يجمع بين روعة الطبيعة وسحر التفاصيل. يتكوّن هذا التنسيق من 20 روز وردية غامقة تنبض بالحيوية والرقي، تتوسطها 5 أزهار كريزنتيموم بيضاء تضفي لمسة من النقاء والتوازن، مع لمسات من الخضار الطبيعي التي تعزز جمال الترتيب وتمنحه طابعًا عصريًا أنيقًا. تنسيق مثالي لكل مناسبة، يعبّر عن الفخامة بأسلوب بسيط وجذاب.</p>\\n<p>الارتفاع حوالي 30 سم.</p>\\n<p>العرض حوالي 25 سم.</p>\"}', '141', 'products/101-65.png', '[\"products\\/gallery\\/101-65.png\",\"products\\/gallery\\/104-55.png\",\"products\\/gallery\\/103-59.png\",\"products\\/gallery\\/102-61.png\"]', '{\"en\":\"<p>تألّق بتصميم زهري يعكس الأناقة والذوق الرفيع، يجمع بين روعة الطبيعة وسحر التفاصيل. يتكوّن هذا التنسيق من 20 روز وردية غامقة تنبض بالحيوية والرقي، تتوسطها 5 أزهار كريزنتيموم بيضاء تضفي لمسة من النقاء والتوازن، مع لمسات من الخضار الطبيعي التي تعزز جمال الترتيب وتمنحه طابعًا عصريًا أنيقًا. تنسيق مثالي لكل مناس