INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('404', '17922', NULL, '[4,6,7,22,23,24,32,44,57]', NULL, NULL, NULL, '{\"en\":\"G058\",\"ar\":\"G058\"}', 'g058-2', 'g058-2', '{\"en\":\"<p>تتميز هذه التشكيلة الفاخرة من الورد الأبيض والبيبي أوركيد الأبيض بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. تضم التشكيلة 12 روز بيضاء ناعمة و10 أوركيد بيبي أبيض، مع تنسيق متقن يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.</p>\\n<p>الارتفاع حوالي 20 سم.</p>\\n<p>العرض حوالي 20 سم.</p>\",\"ar\":\"<p>تتميز هذه التشكيلة الفاخرة من الورد الأبيض والبيبي أوركيد الأبيض بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. تضم التشكيلة 12 روز بيضاء ناعمة و10 أوركيد بيبي أبيض، مع تنسيق متقن يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.</p>\\n<p>الارتفاع حوالي 20 سم.</p>\\n<p>العرض حوالي 20 سم.</p>\"}', '129', 'products/1-35.png', '[\"products\\/gallery\\/1-35.png\",\"products\\/gallery\\/2-37.png\",\"products\\/gallery\\/3-36.png\",\"products\\/gallery\\/4-33.png\"]', '{\"en\":\"<p>تتميز هذه التشكيلة الفاخرة من الورد الأبيض والبيبي أوركيد الأبيض بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. تضم التشكيلة 12 روز بيضاء ناعمة و10 أوركيد بيبي أبيض، مع تنسيق متقن يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تع