INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('423', '17972', NULL, '[4,6,7,9,19,21,23,24,32,46]', NULL, NULL, NULL, '{\"en\":\"G015\",\"ar\":\"G015\"}', 'g015-2', 'g015-2', '{\"en\":\"<p>تأسر الأنظار ببساطتها وأناقتها، تنسيق <i>روز أحمر 35</i> يجمع بين الفخامة والرقي في آنٍ واحد. باقة من 35 وردة حمراء طبيعية تنبض بالحياة، مرتبة بعناية داخل وعاء زجاجي أنيق يلفه شريط أسود فاخر، لتعبّر عن المشاعر الصادقة بأسلوب راقٍ يناسب كل المناسبات، من التهاني الرسمية إلى لحظات الحب والامتنان.</p>\\n<p>الارتفاع حوالي 30 سم.</p>\\n<p>العرض حوالي 36 سم.</p>\",\"ar\":\"<p>تأسر الأنظار ببساطتها وأناقتها، تنسيق <i>روز أحمر 35</i> يجمع بين الفخامة والرقي في آنٍ واحد. باقة من 35 وردة حمراء طبيعية تنبض بالحياة، مرتبة بعناية داخل وعاء زجاجي أنيق يلفه شريط أسود فاخر، لتعبّر عن المشاعر الصادقة بأسلوب راقٍ يناسب كل المناسبات، من التهاني الرسمية إلى لحظات الحب والامتنان.</p>\\n<p>الارتفاع حوالي 30 سم.</p>\\n<p>العرض حوالي 36 سم.</p>\"}', '86', 'products/1-33.png', '[\"products\\/gallery\\/1-33.png\",\"products\\/gallery\\/2-35.png\",\"products\\/gallery\\/3-34.png\",\"products\\/gallery\\/4-32.png\",\"products\\/gallery\\/5-17.png\"]', '{\"en\":\"<p>تأسر الأنظار ببساطتها وأناقتها، تنسيق <i>روز أحمر 35</i> يجمع بين الفخامة والرقي في آنٍ واحد. باقة من 35 وردة حمراء طبيعية تنبض بالحياة، مرتبة بعناية داخل وعاء زجاجي أنيق يلفه شريط أسود فاخر، لتعبّر عن المشاعر الصادقة بأسلوب راقٍ يناسب كل المناسبات، من التهاني الرسمية إلى لحظات الحب والامتنان.</p>\\n<p>الارتفاع حوالي 30 سم.</p>\\n<p>العرض حوالي 36 سم.</p>\",\"ar\":\"<p>تأسر الأنظار ببساطتها وأناقتها، تنسيق <i>روز أحمر 35</i> يجمع بين الفخامة والرقي في آنٍ واحد. باقة من 35 وردة حمراء طبيعية تنبض بالحياة، مرتبة بعناية داخل وعاء زجاجي أنيق يلفه شريط أسود فاخر، لتعبّر عن المشاعر الصادقة بأسلوب راقٍ يناسب كل المناسبات، من التهاني الرسمية إلى لحظات الحب والامتنان.</p>\\n<p>الارتفاع حوالي 30 سم.</p>\\n<p>العرض حوالي 36 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":198,\"name\":\"\\u0623\\u062d\\u0645\\u0631\",\"slug\":\"%d8%a3%d8%ad%d9%85%d8%b1\"},{\"id\":193,\"name\":\"\\u0627\\u0639\\u062a\\u0630\\u0627\\u0631\",\"slug\":\"%d8%a7%d8%b9%d8%aa%d8%b0%d8%a7%d8%b1\"},{\"id\":221,\"name\":\"\\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u0647\\u0648\\u0631\",\"slug\":\"%d8%ac%d9%85%d9%8a%d8%b9-%d8%a7%d9%84%d8%b2%d9%87%d9%88%d8%b1\"},{\"id\":210,\"name\":\"\\u062d\\u0628\",\"slug\":\"%d8%ad%d8%a8\"},{\"id\":237,\"name\":\"\\u0641\\u0644\\u0646\\u062a\\u0627\\u064a\\u0646\",\"slug\":\"%d9%81%d9%84%d9%86%d8%aa%d8%a7%d9%8a%d9%86\"},{\"id\":208,\"name\":\"\\u0644\\u0644\\u0623\\u0645\",\"slug\":\"%d9%84%d9%84%d8%a3%d9%85\"},{\"id\":196,\"name\":\"\\u0644\\u0644\\u0631\\u062c\\u0644\",\"slug\":\"%d9%84%d9%84%d8%b1%d8%ac%d9%84\"},{\"id\":195,\"name\":\"\\u0644\\u0644\\u0645\\u0631\\u0623\\u0629\",\"slug\":\"%d9%84%d9%84%d9%85%d8%b1%d8%a3%d8%a9\"},{\"id\":212,\"name\":\"\\u0645\\u0648\\u0644\\u0648\\u062f \\u062c\\u062f\\u064a\\u062f\",\"slug\":\"%d9%85%d9%88%d9%84%d9%88%d8%af-%d8%ac%d8%af%d9%8a%d8%af\"},{\"id\":213,\"name\":\"\\u0648\\u0638\\u064a\\u0641\\u0629 \\u0648\\u062a\\u0631\\u0642\\u064a\\u0629\",\"slug\":\"%d9%88%d8%b8%d9%8a%d9%81%d8%a9-%d9%88%d8%aa%d8%b1%d9%82%d9%8a%d8%a9\"}],\"tags\":[],\"wp_ar_id\":17972}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '300.00', '300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'Other', NULL, NULL, '2026-10-01 15:21:18', '2026-10-07 12:45:16', NULL);
