INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('427', '17986', NULL, '[3,6,16,19,20,22,23,27,32,53]', NULL, NULL, NULL, '{\"en\":\"G005\",\"ar\":\"G005\"}', 'g005-2', 'g005-2', '{\"en\":\"<p>باقة فاخرة تنبض بالأناقة والرقي، تجمع بين جمال ورد جوري باللون دبل فوشي والهيدرينجيا الاخضر ونقاء الكريزنتيموم الابيض، تتخللها لمسات من الستيل غراس التي تضيف انسيابية طبيعية ولمسة عصرية مبهرة. توليفة متناغمة من الألوان والأنسجة تعبّر عن الفخامة والحيوية في آنٍ واحد، لتكون الهدية المثالية لكل مناسبة تنبض بالمشاعر الراقية.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>باقة فاخرة تنبض بالأناقة والرقي، تجمع بين جمال ورد جوري باللون دبل فوشي والهيدرينجيا الاخضر ونقاء الكريزنتيموم الابيض، تتخللها لمسات من الستيل غراس التي تضيف انسيابية طبيعية ولمسة عصرية مبهرة. توليفة متناغمة من الألوان والأنسجة تعبّر عن الفخامة والحيوية في آنٍ واحد، لتكون الهدية المثالية لكل مناسبة تنبض بالمشاعر الراقية.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '76', 'products/101-72.png', '[\"products\\/gallery\\/101-72.png\",\"products\\/gallery\\/102-67.png\",\"products\\/gallery\\/103-66.png\",\"products\\/gallery\\/104-60.png\"]', '{\"en\":\"<p>باقة فاخرة تنبض بالأناقة والرقي، تجمع بين جمال ورد جوري باللون دبل فوشي والهيدرينجيا الاخضر ونقاء الكريزنتيموم الابيض، تتخللها لمسات من الستيل غراس التي تضيف انسيابية طبيعية ولمسة عصرية مبهرة. توليفة متناغمة من الألوان والأنسجة تعبّر عن الفخامة والحيوية في آنٍ واحد، لتكون الهدية المثالية لكل مناسبة تنبض بالمشاعر الراقية.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\