INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('428', '17988', NULL, '[3,4,6,11,18,19,32,48,49]', NULL, NULL, NULL, '{\"en\":\"G003\",\"ar\":\"G003\"}', 'g003-2', 'g003-2', '{\"en\":\"<p>أهدي من يعز عليك هذه الفازة المميزة التي تقدّم مزيجاً رائعاً من الألوان الطبيعية مع تنوع نباتي مذهل. يتضمن الفازة الرائعة 15 حبة من بيبي أوركيد سونيا ذات الألوان الزاهية، 4 حبات من هايدرنجا الأبيض الفاخر، 4 حبات من كيرميت الأخضر التي تضيف لمسة من الحيوية، بالإضافة إلى 5 حبات من كالا الأبيض الرائع، وكريزنتيموم بنفسجي أربع قطع. كل هذه الزهور مرتبة بعناية فائقة لتعكس تناغم الألوان والأناقة. هذا التنسيق هو الخيار المثالي لإضافة لمسة من الفخامة والجمال إلى أي مكان.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\",\"ar\":\"<p>أهدي من يعز عليك هذه الفازة المميزة التي تقدّم مزيجاً رائعاً من الألوان الطبيعية مع تنوع نباتي مذهل. يتضمن الفازة الرائعة 15 حبة من بيبي أوركيد سونيا ذات الألوان الزاهية، 4 حبات من هايدرنجا الأبيض الفاخر، 4 حبات من كيرميت الأخضر التي تضيف لمسة من الحيوية، بالإضافة إلى 5 حبات من كالا الأبيض الرائع، وكريزنتيموم بنفسجي أربع قطع. كل هذه الزهور مرتبة بعناية فائقة لتعكس تناغم الألوان والأناقة. هذا التنسيق هو الخيار المثالي لإضافة لمسة من الفخامة والجمال إلى أي مكان.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 30 سم.</p>\"}', '74', 'products/101-78.png', '[\"products\\/gallery\\/101-78.png\",\"products\\/gallery\\/102-75.png\",\"products\\/gallery\\/103-72.png\",\"products\\/gallery\\/104-66.png\",\"products\\/gallery\\/106-10.png\"]', '{\"en\":\"<p>أهدي من يعز عليك هذه الفازة المميزة التي تق