INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('441', '88479', NULL, '[18,32]', NULL, NULL, NULL, '{\"en\":\"G848\",\"ar\":\"G848\"}', 'g848', 'g848', '{\"en\":\"<p>باقة زهور في فازة على شكل دب لطيف صُممت بعناية فائقة على يد خبرائنا، الذين أبدعوا في تنسيقها بذوق رفيع لتمنحك انطباعًا جماليًا راقيًا وحصريًا. مزيج متناغم من الخضرة والأزهار الطبيعية، تُقدَّم بكل تألق لمناسبات مولود، لتُخلّد لحظاتهم بلحظات لا تُنسى.</p>\\n<p>تضم الباقة من الأزهار المختارة بعناية من الكريزنتيموم بالأبيض والتي تحتوي على 7 حبات ,مع 17 حبة من الكيرمت الأخضر ولمسات أنيقة من الأعشاب الموس لتعزيز الجمالية بالخضارات الطبيعية, باقة حديثة مناسبة لجميع لأذواق.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\",\"ar\":\"<p>باقة زهور في فازة على شكل دب لطيف صُممت بعناية فائقة على يد خبرائنا، الذين أبدعوا في تنسيقها بذوق رفيع لتمنحك انطباعًا جماليًا راقيًا وحصريًا. مزيج متناغم من الخضرة والأزهار الطبيعية، تُقدَّم بكل تألق لمناسبات مولود، لتُخلّد لحظاتهم بلحظات لا تُنسى.</p>\\n<p>تضم الباقة من الأزهار المختارة بعناية من الكريزنتيموم بالأبيض والتي تحتوي على 7 حبات ,مع 17 حبة من الكيرمت الأخضر ولمسات أنيقة من الأعشاب الموس لتعزيز الجمالية بالخضارات الطبيعية, باقة حديثة مناسبة لجميع لأذواق.</p>\\n<p>الارتفاع حوالي 40 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\"}', 'GF-WP-88479', 'products/102-12.png', '[\"products\\/gallery\\/102-12.png\",\"products\\/gallery\\/101-12.png\",\"products\\/gallery\\/104-11.png\",\"products\\/gallery\\/105-7.png\",\"products\\/gallery\\/103-11.png\"]', '{\"en\":\"<p>باقة زهور في فازة على شكل دب لطيف صُممت بعناي