INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('472', '89474', NULL, '[41]', NULL, NULL, NULL, '{\"en\":\"G855\",\"ar\":\"G855\"}', 'g855', 'g855', '{\"en\":\"<p>هذه الهدية المميزة تجمع بين الجمال الطبيعي والرقي الفاخر. عبارة عن تركيبة ساحرة من 25 وردة روز حمراء ناعمة، وحبتان هايبركوم أحمر مغطاة بعناية حول حبات الفراولة الطازجة التي تضفي عليها لمسة من الانتعاش والطعم اللذيذ. بالإضافة إلى ذلك، فإن الزهور مع الخضار الرفيع في التصميم يخلق توازنًا بين الجمال الطبيعي واللمسات الرفيعة. تُختتم هذه الهدية الجميلة بشريط أسود أنيق، مما يجعلها مثالية للمناسبات الخاصة مثل عيد الحب أو الاحتفالات المميزة.   </p>\\n<p>الارتفاع حوالي 25 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\",\"ar\":\"<p>هذه الهدية المميزة تجمع بين الجمال الطبيعي والرقي الفاخر. عبارة عن تركيبة ساحرة من 25 وردة روز حمراء ناعمة، وحبتان هايبركوم أحمر مغطاة بعناية حول حبات الفراولة الطازجة التي تضفي عليها لمسة من الانتعاش والطعم اللذيذ. بالإضافة إلى ذلك، فإن الزهور مع الخضار الرفيع في التصميم يخلق توازنًا بين الجمال الطبيعي واللمسات الرفيعة. تُختتم هذه الهدية الجميلة بشريط أسود أنيق، مما يجعلها مثالية للمناسبات الخاصة مثل عيد الحب أو الاحتفالات المميزة.   </p>\\n<p>الارتفاع حوالي 25 سم.</p>\\n<p>العرض حوالي 35 سم.</p>\"}', 'GF-WP-89474', 'products/102-8.png', '[\"products\\/gallery\\/102-8.png\",\"products\\/gallery\\/103-11.png\",\"products\\/gallery\\/104-5.png\",\"products\\/gallery\\/101-16.png\"]', '{\"en\":\"<p>هذه الهدية المميزة تجمع بين الجمال الطبيعي والرقي الفاخر. عبارة عن تركيبة ساحرة من 25 وردة روز حمراء ناعمة، وحبتان هايبركوم أحمر مغطاة بعناية حول حب